import { useMemo, useState } from 'react'

import { TriageList } from './TriageList'
import type { LeakReport } from './types'

interface LeakTriageSearchProps {
  reports: LeakReport[]
  onSaveNote: (reportId: string, note: string) => void
  onDismiss: (reportId: string) => void
}

const statusOptions = [
  { value: 'all', label: 'Any status' },
  { value: 'reported', label: 'Reported' },
  { value: 'surveyed', label: 'Surveyed' },
  { value: 'scheduled', label: 'Crew scheduled' },
]

const controlClass =
  'rounded-lg border border-zinc-300 bg-white px-4 py-2 text-base text-zinc-900 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100'

export function LeakTriageSearch({ reports, onSaveNote, onDismiss }: LeakTriageSearchProps) {
  const [ward, setWard] = useState('all')
  const [status, setStatus] = useState('all')

  const wards = useMemo(
    () => Array.from(new Set(reports.map((report) => report.ward))).sort((a, b) => a - b),
    [reports],
  )

  const rows = useMemo(
    () =>
      reports.filter(
        (report) =>
          (ward === 'all' || String(report.ward) === ward) &&
          (status === 'all' || report.status === status),
      ),
    [reports, ward, status],
  )

  return (
    <section className="mx-auto flex max-w-7xl flex-col gap-6">
      <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        Leak triage
      </h2>
      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        <div className="flex flex-col gap-2">
          <label htmlFor="triage-ward" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
            Ward
          </label>
          <select
            id="triage-ward"
            value={ward}
            onChange={(event) => setWard(event.target.value)}
            className={controlClass}
          >
            <option value="all">Every ward</option>
            {wards.map((wardNumber) => (
              <option key={wardNumber} value={String(wardNumber)}>
                Ward {wardNumber}
              </option>
            ))}
          </select>
        </div>
        <div className="flex flex-col gap-2">
          <label htmlFor="triage-status" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
            Status
          </label>
          <select
            id="triage-status"
            value={status}
            onChange={(event) => setStatus(event.target.value)}
            className={controlClass}
          >
            {statusOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>
        <p className="self-end text-sm tabular-nums text-zinc-600 dark:text-zinc-400">
          {rows.length} of {reports.length} reports
        </p>
      </div>
      <TriageList rows={rows} onSaveNote={onSaveNote} onDismiss={onDismiss} />
    </section>
  )
}

import { render, screen } from '@testing-library/react'
