import { useEffect, useState } from 'react'

import { searchSubstations } from './api'
import type { Substation } from './types'

export function useSubstationSearch(query: string) {
  const [results, setResults] = useState<Substation[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    if (query.trim().length < 2) {
      setResults([])
      return
    }
    setIsLoading(true)
    searchSubstations(query)
      .then((found) => {
        setResults(found)
        setIsLoading(false)
      })
      .catch(() => {
        setError('Substation search is not responding.')
        setIsLoading(false)
      })
  }, [query])

  return { results, isLoading, error }
}

import type { Substation } from './types'

const BASE = '/api/heat/substations'

export async function searchSubstations(query: string, signal?: AbortSignal): Promise<Substation[]> {
  const response = await fetch(`${BASE}?q=${encodeURIComponent(query)}`, { signal })
  if (!response.ok) {
    throw new Error(`Substation lookup failed with status ${response.status}`)
  }
  return (await response.json()) as Substation[]
}

