import type { SurveyReading } from './types'

export interface ReadingFilters {
  kind: 'all' | 'pressure' | 'flow'
  minPsi: number
  minGpm: number
}

/**
 * Narrows one cathodic protection survey run for the readings search. Pressure
 * readings carry psi, flow readings carry gpm, and a run mixes both kinds.
 */
export function filterReadings(readings: SurveyReading[], filters: ReadingFilters): SurveyReading[] {
  const { kind, minPsi, minGpm } = filters
  return readings.filter((reading) => {
    if (kind !== 'all' && reading.kind !== kind) return false
    return reading.psi >= minPsi && reading.gpm >= minGpm
  })
}

