import { useRef, useState } from 'react'

import { patchCustodianOrder } from '../../api/holds'
import type { Custodian } from './types'

export function useCustodianOrder(holdId: string, initial: Custodian[]) {
  const [custodians, setCustodians] = useState(initial)
  const [saveError, setSaveError] = useState<string | null>(null)
  const queueRef = useRef<Promise<void>>(Promise.resolve())
  const sentRef = useRef(0)

  async function saveOrder(next: Custodian[]) {
    setCustodians(next)
    setSaveError(null)
    sentRef.current += 1
    const mine = sentRef.current
    queueRef.current = queueRef.current.then(async () => {
      try {
        const res = await patchCustodianOrder(holdId, next.map((custodian) => custodian.id))
        if (mine === sentRef.current) setCustodians(res.custodians)
      } catch {
        setSaveError('Could not save the notice order. Retry before the hold goes out.')
      }
    })
    await queueRef.current
  }

  function moveCustodian(from: number, to: number) {
    if (to < 0 || to >= custodians.length) return
    const next = custodians.slice()
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    void saveOrder(next)
  }

  return { custodians, saveError, moveCustodian }
}

