  { id: 'tm-9930', mark: 'CLEARFIELD', owner: 'Clearfield Holdings', dueOn: '2026-10-02', source: 'filings' },
  { id: 4822, mark: 'VOSS ATLAS', owner: 'Harbert Voss LLP', dueOn: '2026-11-30', source: 'docketing' },
]

const savedPositions = { 'tm-9930': 1, '4821': 2, '4822': 3 }

describe('sortByDocketPosition', () => {
  it('keeps the saved docket order after a drag', () => {
    const ordered = sortByDocketPosition(rows, savedPositions)
    expect(ordered.map((row) => row.id)).toEqual(['tm-9930', 4821, 4822])
  })

  it('does not disturb rows that already sit in saved order', () => {
    const ordered = sortByDocketPosition(rows, { '4821': 1, '4822': 2, 'tm-9930': 3 })
    expect(ordered.map((row) => row.id)).toEqual([4821, 4822, 'tm-9930'])
  })
})

import type { RenewalRow } from './types'

export function sortByDocketPosition(rows: RenewalRow[], positions: Record<string, number>) {
  const positionById = new Map(Object.entries(positions))

  return rows.slice().sort((a, b) => {
    const left = positionById.get(a.id as string) ?? 0
    const right = positionById.get(b.id as string) ?? 0
    return left - right
  })
}

