import { useEffect, useState } from 'react'

import { fetchCycleTimes } from '../api/cycleTimes'
import { toSeries } from './toSeries'
import type { CycleTimePoint, DateRange } from './types'

export function useCycleTimeSeries(pressId: string, range: DateRange) {
  const [series, setSeries] = useState<CycleTimePoint[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let active = true
    setLoading(true)
    setError(null)

    fetchCycleTimes(pressId, range)
      .then((shots) => {
        if (!active) return
        if (shots.length === 0) return
        setSeries(toSeries(shots))
        setLoading(false)
      })
      .catch((err: unknown) => {
        if (!active) return
        setError(err instanceof Error ? err.message : 'Cycle times could not be loaded.')
        setLoading(false)
      })

    return () => {
      active = false
    }
  }, [pressId, range.from, range.to])

  return { series, loading, error }
}

