import { beforeEach, describe, expect, it, vi } from 'vitest'

import { fetchCycleTimes } from '../api/cycleTimes'
import { useCycleTimeSeries } from './useCycleTimeSeries'

vi.mock('../api/cycleTimes', () => ({ fetchCycleTimes: vi.fn() }))

const range = { from: '2026-07-20', to: '2026-07-27' }

describe('useCycleTimeSeries', () => {
  beforeEach(() => {
    vi.mocked(fetchCycleTimes).mockReset()
  })

  it('stops loading when the press logged no shots in the range', async () => {
    vi.mocked(fetchCycleTimes).mockResolvedValue([])
    const { result } = renderHook(() => useCycleTimeSeries('press-04', range))

    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.series).toEqual([])
    expect(result.current.error).toBeNull()
  })

  it('stops loading and reports the reason when the range request fails', async () => {
    vi.mocked(fetchCycleTimes).mockRejectedValue(new Error('Historian timed out after 30s'))
