import { memo } from 'react'

import type { ChartOverlay, YieldPoint } from './types'

interface YieldTrendChartProps {
  baseline: YieldPoint[]
  lotSeries: Record<string, YieldPoint[]>
  overlay: ChartOverlay
}

const WIDTH = 720
const HEIGHT = 240

function toPolyline(points: YieldPoint[]) {
  return points
    .map((point, index) => {
      const x = (index / Math.max(points.length - 1, 1)) * WIDTH
      const y = HEIGHT - (point.yieldPercent / 100) * HEIGHT
      return `${x.toFixed(1)},${y.toFixed(1)}`
    })
    .join(' ')
}

export const YieldTrendChart = memo(function YieldTrendChart({ baseline, lotSeries, overlay }: YieldTrendChartProps) {
  return (
    <figure className="flex flex-col gap-4">
      <svg
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        role="img"
        aria-label="Fab yield by work week"
        className="h-60 w-full"
      >
        <polyline
          points={toPolyline(baseline)}
          fill="none"
          strokeWidth={2}
          className="stroke-zinc-400 dark:stroke-zinc-500"
        />
      </svg>
      <figcaption className="flex flex-wrap gap-6 text-sm text-zinc-700 dark:text-zinc-300">
        <span>Fab baseline, all lots</span>
      </figcaption>
    </figure>
  )
})

