import { describe, expect, it } from 'vitest'

import { useChartConfig } from './useChartConfig'
import { YieldTrendChart } from './YieldTrendChart'
import type { ChartConfig, YieldPoint } from './types'

const baseline: YieldPoint[] = [
  { workWeek: 'WW26', yieldPercent: 91.4 },
  { workWeek: 'WW27', yieldPercent: 92.1 },
]

const lotSeries: Record<string, YieldPoint[]> = {
  'L26-4471': [
    { workWeek: 'WW26', yieldPercent: 84.7 },
    { workWeek: 'WW27', yieldPercent: 88.2 },
  ],
}

const initial: ChartConfig = { windowWeeks: 8, overlay: { lotId: null } }

describe('lot overlay', () => {
  it('gives the memoized chart a new overlay object when the lot changes', () => {
    const { result } = renderHook(() => useChartConfig(initial))
    const before = result.current.config.overlay

    act(() => result.current.setOverlayLot('L26-4471'))

    expect(result.current.config.overlay).not.toBe(before)
    expect(result.current.config.overlay.lotId).toBe('L26-4471')
    expect(initial.overlay.lotId).toBeNull()
  })

  it('draws the lot line and names the lot in the legend', () => {
    render(<YieldTrendChart baseline={baseline} lotSeries={lotSeries} overlay={{ lotId: 'L26-4471' }} />)

    expect(screen.getByText('Lot L26-4471')).toBeInTheDocument()
    expect(screen.getByTestId('lot-overlay-line')).toHaveAttribute('points', '0.0,36.7 720.0,28.3')
  })

  it('draws baseline only when no lot is selected', () => {
    render(<YieldTrendChart baseline={baseline} lotSeries={lotSeries} overlay={{ lotId: null }} />)

    expect(screen.queryByTestId('lot-overlay-line')).not.toBeInTheDocument()
    expect(screen.getByText('Fab baseline, all lots')).toBeInTheDocument()
  })
})

