import { useState } from 'react'

import { saveRegistryOrder } from './api'
import type { RegistryItem } from './types'

interface RegistryEditorProps {
  registryId: string
  items: RegistryItem[]
}

export function RegistryEditor({ registryId, items }: RegistryEditorProps) {
  const [order, setOrder] = useState(items)
  const [toast, setToast] = useState<string | null>(null)

  function handleMoveToTop(itemId: string) {
    const next = [
      ...order.filter((item) => item.id === itemId),
      ...order.filter((item) => item.id !== itemId),
    ]
    setOrder(next)
    saveRegistryOrder(registryId, next.map((item) => item.id))
    setToast('Registry saved')
  }

  function handleRestoreSuggested() {
    setOrder(items)
    saveRegistryOrder(registryId, items.map((item) => item.id))
    setToast('Registry saved')
  }

  return (
    <div className="flex flex-col gap-6">
      <ul className="flex flex-col gap-2">
        {order.map((item) => (
          <li key={item.id} className="flex items-center justify-between gap-4 rounded-lg border border-zinc-200 px-4 py-3 dark:border-zinc-800">
            <span className="min-w-0 truncate text-base text-zinc-900 dark:text-zinc-100" title={item.name}>{item.name}</span>
            <button type="button" onClick={() => handleMoveToTop(item.id)} className="min-h-11 rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-rose-700 focus-visible:ring-offset-2 dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900">
              Move to top
            </button>
          </li>
        ))}
      </ul>
      <button type="button" onClick={handleRestoreSuggested} className="self-start text-sm font-medium text-rose-700 underline focus-visible:ring-2 focus-visible:ring-rose-700 focus-visible:ring-offset-2 dark:text-rose-400">
        Restore suggested order
      </button>
      {toast ? (
        <p className="rounded-lg bg-emerald-700 px-4 py-2 text-sm font-medium text-white dark:bg-emerald-600">{toast}</p>
      ) : null}
    </div>
  )
}

export type ToastTone = 'success' | 'error'

export interface Toast {
  id: string
  tone: ToastTone
  message: string
}

let seq = 0
let toasts: Toast[] = []
const listeners = new Set<(next: Toast[]) => void>()

export function notifyToast(tone: ToastTone, message: string) {
  seq += 1
  toasts = [...toasts, { id: 'toast-' + seq, tone, message }]
  listeners.forEach((listener) => listener(toasts))
}

export function dismissToast(id: string) {
  toasts = toasts.filter((toast) => toast.id !== id)
  listeners.forEach((listener) => listener(toasts))
}

export function subscribeToasts(listener: (next: Toast[]) => void) {
  listeners.add(listener)
  listener(toasts)
  return () => {
    listeners.delete(listener)
  }
}

