import { useState, type FormEvent } from 'react'

import { notifyToast } from '../shared/notify'
import { reloadGiftCard } from './giftCardApi'

interface ReloadGiftCardDialogProps {
  cardId: string
  last4: string
  onClose: () => void
}

function formatUsd(cents: number) {
  return (cents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })
}

export function ReloadGiftCardDialog({ cardId, last4, onClose }: ReloadGiftCardDialogProps) {
  const [amount, setAmount] = useState('25.00')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const cents = Math.round(Number(amount) * 100)
    setSubmitting(true)
    setError(null)
    try {
      const receipt = await reloadGiftCard(cardId, cents)
      notifyToast('success', formatUsd(cents) + ' added to card ' + last4 + ', receipt ' + receipt.id)
      // The toast lives on the app shell, so it outlives this dialog. Close last, and write no state after it.
      onClose()
    } catch {
      setSubmitting(false)
      setError('The gift card service did not answer. Nothing was charged to the customer.')
    }
  }

  return (
    <form onSubmit={handleSubmit} aria-labelledby="reload-title" className="flex flex-col gap-6">
      <h2 id="reload-title" className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        Reload card ending {last4}
      </h2>
      <div className="flex flex-col gap-2">
        <label htmlFor="reload-amount" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
          Amount to add
        </label>
        <input
          id="reload-amount"
          type="number"
          inputMode="decimal"
          step="0.01"
          value={amount}
          onChange={(event) => setAmount(event.target.value)}
          aria-invalid={error !== null}
          aria-describedby={error === null ? undefined : 'reload-error'}
          className="rounded-lg border border-zinc-300 px-4 py-2 text-base tabular-nums text-zinc-900 transition-colors focus-visible:ring-2 focus-visible:ring-indigo-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
        />
        {error === null ? null : (
          <p id="reload-error" role="alert" className="text-sm leading-relaxed text-red-700 dark:text-red-400">
            {error}
          </p>
        )}
      </div>
      <div className="flex items-center gap-4">
        <button
          type="submit"
          disabled={submitting}
          className="min-h-11 rounded-lg bg-indigo-700 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-indigo-800 focus-visible:ring-2 focus-visible:ring-indigo-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:bg-indigo-600 dark:hover:bg-indigo-500"
        >
          {submitting ? 'Reloading' : 'Reload card'}
        </button>
        <button
          type="button"
          onClick={onClose}
          className="min-h-11 rounded-lg px-4 py-2 text-base font-medium text-zinc-700 transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-indigo-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:text-zinc-300 dark:hover:bg-zinc-900"
        >
          Cancel
        </button>
      </div>
    </form>
  )
}

