import { describe, expect, it, vi } from 'vitest'

import { finalizeAppraisal } from '../api'
import { useAppraisalSubmit } from './useAppraisalSubmit'

vi.mock('../api', () => ({
  fetchValuation: vi.fn(() => Promise.resolve({ tradeInCents: 1428000, source: 'auction-comps' })),
  finalizeAppraisal: vi.fn(() => Promise.resolve()),
}))

const draft = { vin: '1FTFW1E84PKD52117', mileage: 61240, condition: 'good' as const }

describe('useAppraisalSubmit', () => {
  it('clears the progress bar when the appraiser cannot finalize', async () => {
    const { result } = renderHook(() => useAppraisalSubmit({ canPrice: true, canFinalize: false }))

    await act(async () => {
      await result.current.submit(draft)
    })

    expect(result.current.error).toBe('Your role can price a trade-in but not finalize it. Send it to a desk manager.')
    expect(result.current.progress).toBe(0)
    expect(finalizeAppraisal).not.toHaveBeenCalled()
  })

  it('clears the progress bar when the VIN is missing', async () => {
    const { result } = renderHook(() => useAppraisalSubmit({ canPrice: true, canFinalize: true }))

    await act(async () => {
      await result.current.submit({ ...draft, vin: '' })
    })

    expect(result.current.progress).toBe(0)
  })

  it('leaves a finalized appraisal at full progress', async () => {
    const { result } = renderHook(() => useAppraisalSubmit({ canPrice: true, canFinalize: true }))

    await act(async () => {
      await result.current.submit(draft)
    })

    expect(result.current.done).toBe(true)
    expect(result.current.progress).toBe(100)
  })
})

