import type { Lease } from './types'
import { monthlyChargeUsd, terminationLabel } from './leaseFields'

const HEADERS = ['Lease ID', 'Route', 'Strands', 'Term end', 'Monthly charge', 'Termination note']

function csvCell(value: string): string {
  if (/[",\r\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`
  }
  return value
}

export function buildLeaseCsv(leases: Lease[]): string {
  const rows = leases.map((lease) => [
    lease.id,
    lease.route,
    String(lease.strandCount),
    lease.termEnd,
    monthlyChargeUsd(lease),
    terminationLabel(lease),
  ])

  return [HEADERS, ...rows].map((row) => row.map(csvCell).join(',')).join('\r\n')
}

import { describe, expect, it } from 'vitest'

import { buildLeaseCsv } from './buildLeaseCsv'

const leases = [
  {
    id: 'IRU-2291',
    route: 'Ashburn to Reston',
    strandCount: 24,
    termEnd: '2031-06-30',
    monthlyChargeCents: 1875000,
    terminationNotes: '',
  },
  {
    id: 'IRU-2304',
    route: 'Reston to Sterling',
    strandCount: 12,
    termEnd: '2029-12-31',
    monthlyChargeCents: 940000,
    terminationNotes: null,
  },
  {
    id: 'IRU-2318',
