import { useEffect, useState } from 'react'

interface PhotoPreloadState {
  ready: boolean
  loadedCount: number
}

/**
 * Holds the locate packet back until every site photo has decoded, so the print
 * view never captures a half drawn paint mark. A photo that decodes after the
 * crew has paged to another ticket is dropped rather than counted.
 */
export function usePhotoPreload(urls: string[]): PhotoPreloadState {
  const key = urls.join('|')
  const [loadedCount, setLoadedCount] = useState(0)

  useEffect(() => {
    let cancelled = false
    setLoadedCount(0)

    const sources = key === '' ? [] : key.split('|')
    const images = sources.map((source) => {
      const image = new Image()
      const count = () => {
        if (cancelled) {
          return
        }
        setLoadedCount((current) => current + 1)
      }

      image.onload = count
      image.onerror = count
      image.src = source
      return image
    })

    return () => {
      cancelled = true
      images.forEach((image) => {
        image.onload = null
        image.onerror = null
      })
    }
  }, [key])

  return { ready: key !== '' && loadedCount === key.split('|').length, loadedCount }
}

import { act, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { usePhotoPreload } from './usePhotoPreload'

class FakeImage {
  static instances: FakeImage[] = []
  onload: (() => void) | null = null
  onerror: (() => void) | null = null
  src = ''

  constructor() {
    FakeImage.instances.push(this)
  }
}

const urls = [
  'https://photos.signalandspade.net/lt-7742/paint-north.jpg',
  'https://photos.signalandspade.net/lt-7742/paint-south.jpg',
]

function Harness({ photos }: { photos: string[] }) {
  const { ready, loadedCount } = usePhotoPreload(photos)
  return <p>{ready ? 'packet ready' : `waiting on ${photos.length - loadedCount}`}</p>
}

beforeEach(() => {
  FakeImage.instances = []
  vi.stubGlobal('Image', FakeImage)
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('usePhotoPreload', () => {
  it('holds the packet until every photo has decoded', () => {
    render(<Harness photos={urls} />)
    expect(screen.getByText('waiting on 2')).toBeInTheDocument()

    act(() => {
      FakeImage.instances.forEach((image) => image.onload?.())
    })

    expect(screen.getByText('packet ready')).toBeInTheDocument()
  })

  it('drops a photo that decodes after the packet item has gone', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {})
    const { unmount } = render(<Harness photos={urls} />)
    const inFlight = [...FakeImage.instances]

    unmount()
    inFlight.forEach((image) => image.onload?.())

    expect(inFlight.every((image) => image.onload === null)).toBe(true)
    expect(consoleError).not.toHaveBeenCalled()
