export function formatSessionDay(startsAt: string) {
  return new Date(startsAt).toLocaleDateString('en-GB', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  })
}

export function sessionDayKey(value: string | Date) {
  const date = typeof value === 'string' ? new Date(value) : value
  const year = date.getFullYear()
  const month = `${date.getMonth() + 1}`.padStart(2, '0')
  const day = `${date.getDate()}`.padStart(2, '0')
  return `${year}-${month}-${day}`
}

export function groupBySessionDay(sessions: { startsAt: string }[]) {
  const byDay = new Map<string, { startsAt: string }[]>()
  for (const session of sessions) {
    const key = sessionDayKey(session.startsAt)
    const bucket = byDay.get(key)
    if (bucket) bucket.push(session)
    else byDay.set(key, [session])
  }
  return byDay
