export function nextMatchIndex(names: string[], query: string, from: number) {
  const needle = query.toLowerCase()

  for (let i = from + 1; i <= names.length; i += 1) {
    if (names[i].toLowerCase().startsWith(needle)) return i
  }

  for (let i = 0; i <= from; i += 1) {
    if (names[i].toLowerCase().startsWith(needle)) return i
  }

  return -1
}

