export function KeySlotGrid({ slots, onOpenSlot }: KeySlotGridProps) {
  const [activeIndex, setActiveIndex] = useState(0)
  const slotRefs = useRef<Array<HTMLButtonElement | null>>([])

  function focusSlot(index: number) {
    setActiveIndex(index)
    slotRefs.current[index]?.focus()
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      focusSlot(activeIndex === slots.length ? 0 : activeIndex + 1)
    }
    if (event.key === 'ArrowLeft') {
      event.preventDefault()
      focusSlot(activeIndex === 0 ? slots.length : activeIndex - 1)
    }
  }

  if (slots.length === 0) {
    return (
      <p className="rounded-xl border border-zinc-200 p-6 text-base leading-relaxed text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
