export function ExpectedVisitors({ siteId }: ExpectedVisitorsProps) {
  const { visitors, isLoading, error, reload } = useExpectedVisitors(siteId)
  const showSkeleton = !isLoading && visitors.length === 0

  if (error) {
    return (
      <div className="flex flex-col items-start gap-4 rounded-xl border border-red-300 p-6 dark:border-red-900">
