          onClick={reload}
          className="rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900"
        >
          Try again
        </button>
      </div>
    )
  }

  if (showSkeleton) {
    return <VisitorSkeleton rows={6} />
  }

  if (visitors.length === 0) {
    return (
      <p className="rounded-xl border border-zinc-200 p-6 text-base leading-relaxed text-zinc-700 dark:border-zinc-800">
        No visitors expected at this entrance today. Walk ins are booked in at the desk.
      </p>
    )
  }

  return (
    <ul className="flex flex-col gap-2">
      {visitors.map((visitor) => (
        <li
          key={visitor.id}
          className="flex min-h-11 items-center justify-between gap-4 rounded-xl border border-zinc-200 px-4 py-3 dark:border-zinc-800"
        >
          <span className="min-w-0 truncate text-base text-zinc-900 dark:text-zinc-100" title={visitor.name}>
            {visitor.name}
          </span>
          <span className="text-sm tabular-nums text-zinc-600 dark:text-zinc-400">{visitor.dueAtLabel}</span>
