import { daysSince } from './dateUtils'

export interface BenchCalibration {
  lastCalibratedAt: string
  intervalDays: number
}

// The bench API leaves calibration out entirely for units moved over from the
// old rack, so it is optional on the wire.
export interface BenchApiEntry {
  sensorId: string
  label: string
  pm25: number
  calibration?: BenchCalibration
}

interface StoredBenchEntry extends BenchApiEntry {
  cachedAt: string
}

export interface BenchCacheEntry {
  sensorId: string
  label: string
  pm25: number
  cachedAt: string
  calibration: BenchCalibration | null
  calibrationAgeDays: number | null
}

const entryKey = (sensorId: string) => `aqbench.entry.${sensorId}`

export function writeBenchEntry(entry: BenchApiEntry) {
  const stored = { ...entry, cachedAt: new Date().toISOString() }
  window.localStorage.setItem(entryKey(entry.sensorId), JSON.stringify(stored))
}

export function readBenchEntry(sensorId: string): BenchCacheEntry | null {
  const raw = window.localStorage.getItem(entryKey(sensorId))
  if (!raw) {
    return null
  }
  const stored = JSON.parse(raw) as StoredBenchEntry
  const calibration = stored.calibration ?? null
  return {
    sensorId: stored.sensorId,
    label: stored.label,
    pm25: stored.pm25,
    cachedAt: stored.cachedAt,
    calibration,
    calibrationAgeDays: calibration ? daysSince(calibration.lastCalibratedAt) : null,
  }
}

