import { act, renderHook } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'

import { useDepthUnit } from '../useDepthUnit'

const cabraVale = { stationId: 'cabra-vale-2', name: 'Cabra Vale 2', depthUnit: 'in' as const }

afterEach(() => {
  window.localStorage.clear()
})

describe('useDepthUnit', () => {
  it('shows mm while the station profile is still on its way', () => {
    const { result } = renderHook(() => useDepthUnit(null))
    expect(result.current.unit).toBe('mm')
  })

  it('follows the station profile when it lands after the cached render', () => {
    const { result, rerender } = renderHook(({ profile }) => useDepthUnit(profile), {
      initialProps: { profile: null as typeof cabraVale | null },
    })
    expect(result.current.unit).toBe('mm')
    rerender({ profile: cabraVale })
    expect(result.current.unit).toBe('in')
  })

  it("keeps a tech's own choice above the station profile", () => {
    const { result, rerender } = renderHook(({ profile }) => useDepthUnit(profile), {
      initialProps: { profile: null as typeof cabraVale | null },
    })
    act(() => {
      result.current.chooseUnit('mm')
    })
    rerender({ profile: cabraVale })
    expect(result.current.unit).toBe('mm')
  })
})

