import { isSurveyActive } from '../features/masts/surveyStatus'
import type { Mast, OfflineBundle } from './types'

const OFFLINE_MAST_LIMIT = 200

export function buildOfflineBundle(masts: Mast[], generatedAt: string): OfflineBundle {
  const included = masts
    .filter((mast) => !isSurveyActive(mast))
    .slice(0, OFFLINE_MAST_LIMIT)

  return {
    generatedAt,
    masts: included,
    truncated: included.length === OFFLINE_MAST_LIMIT,
  }
}

