import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { buildOfflineBundle } from './bundleBuilder'
import type { Mast } from './types'

function mast(id: string, surveyEndsAt: string | null): Mast {
  return {
    id,
    name: `Cairn Dhu ${id}`,
    latitude: 56.82,
    longitude: -4.19,
    hubHeightM: 80,
    surveyEndsAt,
  }
}

beforeEach(() => {
  vi.useFakeTimers()
  vi.setSystemTime(new Date('2026-07-30T09:00:00Z'))
})

afterEach(() => {
  vi.useRealTimers()
})

describe('buildOfflineBundle', () => {
  it('caches the masts whose survey is still running', () => {
    const bundle = buildOfflineBundle(
      [mast('a', '2026-09-30T00:00:00Z'), mast('b', '2026-03-01T00:00:00Z')],
      '2026-07-30T09:00:00Z',
    )
    expect(bundle.masts.map((entry) => entry.id)).toEqual(['a'])
  })

  it('leaves a finished survey out of the bundle', () => {
    const bundle = buildOfflineBundle([mast('b', '2026-03-01T00:00:00Z')], '2026-07-30T09:00:00Z')
    expect(bundle.masts).toEqual([])
  })

  it('treats an open ended survey as running', () => {
    const bundle = buildOfflineBundle([mast('c', null)], '2026-07-30T09:00:00Z')
    expect(bundle.masts.map((entry) => entry.id)).toEqual(['c'])
  })

  it('flags a bundle that hit the offline limit', () => {
    const many = Array.from({ length: 205 }, (_, index) => mast(`m${index}`, null))
    const bundle = buildOfflineBundle(many, '2026-07-30T09:00:00Z')
    expect(bundle.masts).toHaveLength(200)
    expect(bundle.truncated).toBe(true)
  })
})

