          <select
            id="reviewer-sort"
            value={sortKey}
            onChange={(event) => setSortKey(asSortKey(event.target.value))}
            className="rounded-md border border-stone-300 px-4 py-2 text-base text-stone-900 focus-visible:ring-2 focus-visible:ring-amber-700 focus-visible:ring-offset-2 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-100"
