import { useMemo, useState } from 'react'

import type { DigitizationBatchRequest, IssueDay } from '../types'

interface DateRangeStepProps {
  titleId: string
  availableDays: IssueDay[]
  onQueue: (request: DigitizationBatchRequest) => void
}

const LONG_DAY = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'UTC',
})

function eachDay(fromDay: string, toDay: string) {
  const days: string[] = []
  const cursor = new Date(fromDay + 'T00:00:00Z')
  const last = new Date(toDay + 'T00:00:00Z')
  while (cursor < last) {
    days.push(cursor.toISOString().slice(0, 10))
    cursor.setUTCDate(cursor.getUTCDate() + 1)
  }
  return days
}

function countIssues(availableDays: IssueDay[], fromDay: string, toDay: string) {
  return availableDays.filter((day) => day.publishedOn >= fromDay && day.publishedOn <= toDay).length
}

export function DateRangeStep({ titleId, availableDays, onQueue }: DateRangeStepProps) {
  const [fromDay, setFromDay] = useState('')
  const [toDay, setToDay] = useState('')

  const rangeIsUsable = fromDay !== '' && toDay !== '' && fromDay <= toDay
  const summary = useMemo(() => {
    if (!rangeIsUsable) return 'Pick a first and last day of publication.'
    return (
      countIssues(availableDays, fromDay, toDay) +
      ' issues, ' +
      LONG_DAY.format(new Date(fromDay + 'T00:00:00Z')) +
      ' to ' +
      LONG_DAY.format(new Date(toDay + 'T00:00:00Z')) +
      ' inclusive'
    )
  }, [availableDays, fromDay, toDay, rangeIsUsable])

  return (
    <section className="flex flex-col gap-6">
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <div className="flex flex-col gap-2">
          <label htmlFor="from-day" className="text-sm font-medium text-slate-700 dark:text-slate-300">
            First issue day
          </label>
          <input
            id="from-day"
            type="date"
            value={fromDay}
            onChange={(event) => setFromDay(event.target.value)}
            className="rounded-md border border-slate-300 px-4 py-2 text-base tabular-nums text-slate-900 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100"
          />
        </div>
        <div className="flex flex-col gap-2">
          <label htmlFor="to-day" className="text-sm font-medium text-slate-700 dark:text-slate-300">
            Last issue day
          </label>
          <input
            id="to-day"
            type="date"
            value={toDay}
            onChange={(event) => setToDay(event.target.value)}
            className="rounded-md border border-slate-300 px-4 py-2 text-base tabular-nums text-slate-900 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100"
          />
        </div>
      </div>
      <p className="text-base text-slate-700 dark:text-slate-300">{summary}</p>
      <ol className="flex flex-wrap gap-2">
        {eachDay(fromDay || toDay, toDay).map((day) => (
