import { useEffect, useRef, useState } from 'react'

import { StepFooter } from './StepFooter'
import { TranscriptionPanel } from './TranscriptionPanel'
import { useAnnotationStep } from './useAnnotationStep'
import type { AnnotationStepId } from './types'

interface AnnotationWizardProps {
  manuscriptId: string
  onFinish: () => void
}

const STEP_ORDER: AnnotationStepId[] = ['source-check', 'transcription', 'hand-attribution', 'sign-off']
const STEP_TITLES: Record<AnnotationStepId, string> = {
  'source-check': 'Check the source scan',
  transcription: 'Transcribe the marginalia',
  'hand-attribution': 'Attribute the hand',
  'sign-off': 'Sign off for publication',
}

export function AnnotationWizard({ manuscriptId, onFinish }: AnnotationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const stepId = STEP_ORDER[stepIndex]
  const { annotations, isLoading, error, retry } = useAnnotationStep(manuscriptId, stepId)

  useEffect(() => {
    document.title = STEP_TITLES[stepId] + ' - Marginalia'
  }, [stepId])

  return (
    <main className="mx-auto flex min-h-dvh max-w-7xl flex-col gap-8 p-6">
      {isLoading ? (
        <div className="h-8 w-72 animate-pulse rounded-md bg-zinc-200 motion-reduce:animate-none dark:bg-zinc-800" />
      ) : (
        <h1
          ref={headingRef}
          tabIndex={-1}
          className="text-2xl font-semibold leading-tight text-zinc-900 outline-none focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 dark:text-zinc-100"
        >
          {STEP_TITLES[stepId]}
        </h1>
      )}
      {error ? (
        <p role="alert" className="text-base text-red-700 dark:text-red-400">
          Could not load the marginalia for this folio. {error.message}
          <button type="button" onClick={retry} className="ml-4 underline focus-visible:ring-2 focus-visible:ring-violet-700">
            Try again
          </button>
        </p>
      ) : (
        <TranscriptionPanel annotations={annotations} isLoading={isLoading} />
      )}
      <StepFooter
        stepIndex={stepIndex}
        stepCount={STEP_ORDER.length}
        headingRef={headingRef}
        canContinue={!isLoading && !error}
        onAdvance={() => {
          if (stepIndex === STEP_ORDER.length - 1) {
            onFinish()
            return
          }
          setStepIndex(stepIndex + 1)
        }}
        onBack={() => setStepIndex(Math.max(0, stepIndex - 1))}
      />
    </main>
  )
}

