import { useEffect, useRef, useState } from 'react'

import { fetchProofStatus } from '../../api/proofs'
import type { ProofStatus } from './types'

const DEFAULT_INTERVAL_MS = 15000

export function useProofStatusPoll(
  proofId: string,
  onSnapshot: (snapshot: ProofStatus) => void,
  intervalMs: number = DEFAULT_INTERVAL_MS,
) {
  const [lastError, setLastError] = useState<Error | null>(null)
  const onSnapshotRef = useRef(onSnapshot)

  useEffect(() => {
    onSnapshotRef.current = onSnapshot
  })

  useEffect(() => {
    let cancelled = false

    async function tick() {
      try {
        const snapshot = await fetchProofStatus(proofId)
        if (cancelled) return
        onSnapshotRef.current(snapshot)
        setLastError(null)
      } catch (error) {
        if (cancelled) return
        setLastError(error instanceof Error ? error : new Error('Proof status is unavailable'))
      }
    }

    const timer = window.setInterval(tick, intervalMs)
    return () => {
      cancelled = true
      window.clearInterval(timer)
    }
  }, [proofId, intervalMs])

  return { lastError }
}

import { renderHook, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { fetchProofStatus } from '../../api/proofs'
import { useProofStatusPoll } from './useProofStatusPoll'

vi.mock('../../api/proofs', () => ({ fetchProofStatus: vi.fn() }))

const snapshot = {
  proofId: 'pf-3312',
  round: 2,
  state: 'with_printer' as const,
  updatedAt: '2026-06-14T09:12:00Z',
}

beforeEach(() => {
  vi.useFakeTimers()
  vi.mocked(fetchProofStatus).mockResolvedValue(snapshot)
})

afterEach(() => {
  vi.useRealTimers()
  vi.clearAllMocks()
})

describe('useProofStatusPoll', () => {
  it('keeps the interval running when the parent re-renders with a new callback', async () => {
    const { rerender } = renderHook(
      ({ onSnapshot }: { onSnapshot: (next: typeof snapshot) => void }) =>
        useProofStatusPoll('pf-3312', onSnapshot, 5000),
      { initialProps: { onSnapshot: vi.fn() } },
    )

    await vi.advanceTimersByTimeAsync(4000)
    rerender({ onSnapshot: vi.fn() })
    rerender({ onSnapshot: vi.fn() })
    await vi.advanceTimersByTimeAsync(1500)

    await waitFor(() => expect(fetchProofStatus).toHaveBeenCalledTimes(1))
  })

  it('hands each snapshot to the newest callback, not the first one', async () => {
    const first = vi.fn()
    const latest = vi.fn()
    const { rerender } = renderHook(
      ({ onSnapshot }: { onSnapshot: (next: typeof snapshot) => void }) =>
        useProofStatusPoll('pf-3312', onSnapshot, 5000),
      { initialProps: { onSnapshot: first } },
    )

    rerender({ onSnapshot: latest })
    await vi.advanceTimersByTimeAsync(5200)

    await waitFor(() => expect(latest).toHaveBeenCalledWith(snapshot))
    expect(first).not.toHaveBeenCalled()
  })

  it('stops polling once the step unmounts', async () => {
    const { unmount } = renderHook(() => useProofStatusPoll('pf-3312', vi.fn(), 5000))

    await vi.advanceTimersByTimeAsync(5200)
    unmount()
    await vi.advanceTimersByTimeAsync(20000)

    expect(fetchProofStatus).toHaveBeenCalledTimes(1)
  })
})

