import { LotSelectionStep, toggleLotSelection } from './LotSelectionStep'

const lots = [
  { id: 'lot-118', title: 'Bewick, History of British Birds, 1797, two volumes', reserveGbp: 2400 },
  { id: 'lot-119', title: 'Nash, Places, Curwen Press, 1937, in dust jacket', reserveGbp: 1750 },
  { id: 'lot-120', title: 'Bound run of The Ludgate Monthly, 1891 to 1894', reserveGbp: 620 },
]

describe('toggleLotSelection', () => {
  it('returns a new set rather than editing the one it was given', () => {
    const current = new Set(['lot-118'])
    const next = toggleLotSelection(current, 'lot-119')
    expect(next).not.toBe(current)
    expect([...current]).toEqual(['lot-118'])
    expect([...next]).toEqual(['lot-118', 'lot-119'])
  })

  it('drops a lot that was already ticked', () => {
    expect([...toggleLotSelection(new Set(['lot-118', 'lot-119']), 'lot-118')]).toEqual(['lot-119'])
  })
})

