import { useState } from 'react'

import { fetchConditionScore, saveDamageSurvey } from '../../../api/conditionReports'
import type { DamageSurvey } from '../types'

interface DamageSurveyStepProps {
  reportId: string
  initialSurvey: DamageSurvey
  onContinue: (survey: DamageSurvey) => void
}

export function DamageSurveyStep({ reportId, initialSurvey, onContinue }: DamageSurveyStepProps) {
  const [survey, setSurvey] = useState<DamageSurvey>(initialSurvey)
  const [isSaving, setIsSaving] = useState(false)
  const [saveError, setSaveError] = useState<string | null>(null)

  async function saveAndScore() {
    const submitted = survey
    setIsSaving(true)
    setSaveError(null)
    try {
      await saveDamageSurvey(reportId, submitted)
      fetchConditionScore(reportId).then((score) => {
        setSurvey({ ...submitted, score })
      })
    } catch (cause) {
      setSaveError(cause instanceof Error ? cause.message : 'The survey did not reach the register.')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <form
      className="flex flex-col gap-6"
      onSubmit={(event) => {
        event.preventDefault()
        void saveAndScore()
      }}
    >
      <div className="flex flex-col gap-2">
        <label htmlFor="damage-notes" className="text-base font-medium text-teal-950 dark:text-teal-50">
          Damage notes
        </label>
        <p id="damage-notes-help" className="text-sm text-teal-900 dark:text-teal-200">
          Foxing, tears, losses, previous repairs. One observation per line.
        </p>
        <textarea
          id="damage-notes"
          rows={8}
          value={survey.notes}
          aria-describedby="damage-notes-help"
          onChange={(event) => setSurvey({ ...survey, notes: event.target.value })}
          className="rounded-md border border-teal-300 px-4 py-2 text-base leading-relaxed text-teal-950 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 dark:border-teal-800 dark:bg-teal-950 dark:text-teal-50"
        />
      </div>
      {saveError === null ? null : (
        <p role="alert" className="text-base text-red-700 dark:text-red-400">
          {saveError}
        </p>
      )}
      <div className="flex items-center gap-4">
        <button
          type="submit"
          disabled={isSaving}
          className="min-h-11 rounded-md bg-teal-800 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-teal-900 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none dark:bg-teal-700 dark:hover:bg-teal-600"
        >
          {isSaving ? 'Saving the survey' : 'Save and continue'}
        </button>
        <button
          type="button"
          onClick={() => onContinue(survey)}
          className="min-h-11 rounded-md px-4 py-2 text-base font-medium text-teal-900 underline transition-colors hover:text-teal-950 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:text-teal-200"
        >
          Skip scoring for now
        </button>
      </div>
    </form>
  )
}

