import { useState } from 'react'
import type { FormEvent } from 'react'

import type { HandoverNote, RampTeam } from './types'

interface ThreadComposerProps {
  turnaroundId: string
  stand: string
  teams: RampTeam[]
  onSend: (note: HandoverNote) => Promise<void>
}

export function ThreadComposer({ turnaroundId, stand, teams, onSend }: ThreadComposerProps) {
  const [body, setBody] = useState('')
  const [watcherIds, setWatcherIds] = useState<string[]>([])
  const [sending, setSending] = useState(false)

  function toggleWatcher(teamId: string) {
    setWatcherIds((current) =>
      current.includes(teamId) ? current.filter((id) => id !== teamId) : [...current, teamId],
    )
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (body.trim() === '') return
    setSending(true)
    try {
      await onSend({ turnaroundId, body: body.trim(), watcherIds })
      setBody('')
      setWatcherIds([])
    } finally {
      setSending(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-6">
      <div className="flex flex-col gap-2">
        <label htmlFor="handover-body" className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
          Handover note for stand {stand}
        </label>
        <textarea
          id="handover-body"
          value={body}
          onChange={(event) => setBody(event.target.value)}
          rows={4}
          className="rounded-md border border-neutral-300 px-4 py-2 text-base leading-relaxed text-neutral-900 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 dark:border-neutral-700 dark:bg-neutral-950 dark:text-neutral-100"
        />
      </div>
      <fieldset className="flex flex-col gap-2">
        <legend className="text-sm font-medium text-neutral-700 dark:text-neutral-300">Notify teams</legend>
        <div className="flex flex-wrap gap-2">
          {teams.map((team) => (
            <label
              key={team.id}
              onClick={() => toggleWatcher(team.id)}
              className="flex items-center gap-2 rounded-md border border-neutral-300 px-4 py-2 dark:border-neutral-700"
            >
              <input
                type="checkbox"
                checked={watcherIds.includes(team.id)}
                onChange={() => toggleWatcher(team.id)}
                className="h-4 w-4 rounded border-neutral-400 text-sky-700 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 dark:border-neutral-600"
              />
              <span className="text-base text-neutral-900 dark:text-neutral-100">{team.name}</span>
            </label>
          ))}
        </div>
      </fieldset>
      <button
        type="submit"
        disabled={sending || body.trim() === ''}
        className="self-start rounded-md bg-sky-700 px-4 py-2 text-base font-medium text-neutral-50 hover:bg-sky-800 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:bg-sky-600 dark:hover:bg-sky-500"
      >
        {sending ? 'Sending...' : 'Send handover note'}
      </button>
    </form>
  )
}

