export const MENTION_KIND = {
  person: 'person',
  desk: 'desk',
  watch: 'watch',
} as const

export type MentionKind = (typeof MENTION_KIND)[keyof typeof MENTION_KIND]

export const MENTION_LABEL: Record<MentionKind, string> = {
  person: 'Controller',
  desk: 'Duty desk',
  watch: 'Watch team',
}

export function mentionLabel(kind: MentionKind) {
  return MENTION_LABEL[kind]
}

export interface ParsedMention {
  kind: MentionKind
  handle: string
}

export function parseMentionToken(token: string): ParsedMention {
  if (token.startsWith('##')) return { kind: MENTION_KIND.watch, handle: token.slice(2) }
  if (token.startsWith('#')) return { kind: MENTION_KIND.desk, handle: token.slice(1) }
  return { kind: MENTION_KIND.person, handle: token.slice(1) }
}

