import { useCallback, useRef, useState } from 'react'

const DRAG_CLASS = 'dragging-pin'

interface UsePinDragOptions {
  onAnchor: (commentId: string, defectId: string) => void
}

export function usePinDrag({ onAnchor }: UsePinDragOptions) {
  const draggingId = useRef<string | null>(null)
  const [isDragging, setIsDragging] = useState(false)

  const startDrag = useCallback((commentId: string) => {
    draggingId.current = commentId
    setIsDragging(true)
    document.body.classList.add(DRAG_CLASS)
  }, [])

  const endDrag = useCallback(
    (defectId: string | null) => {
      const commentId = draggingId.current
      if (commentId === null || defectId === null) return
      onAnchor(commentId, defectId)
      draggingId.current = null
      setIsDragging(false)
      document.body.classList.remove(DRAG_CLASS)
    },
    [onAnchor],
  )

  return { isDragging, startDrag, endDrag }
}

