  it('takes the drag class back off the body when the pin lands on nothing', () => {
    const onAnchor = vi.fn()
    const { result } = renderHook(() => usePinDrag({ onAnchor }))

    act(() => result.current.startDrag('cm-3391'))
    expect(document.body).toHaveClass('dragging-pin')

    act(() => result.current.endDrag(null))
    expect(document.body).not.toHaveClass('dragging-pin')
    expect(result.current.isDragging).toBe(false)
    expect(onAnchor).not.toHaveBeenCalled()
  })

  it('anchors the comment when the pin lands on a defect line', () => {
    const onAnchor = vi.fn()
    const { result } = renderHook(() => usePinDrag({ onAnchor }))

    act(() => result.current.startDrag('cm-3391'))
    act(() => result.current.endDrag('mel-2211'))

