import { useEffect, useState } from 'react'
import type { RefObject } from 'react'

const PILL_SHOWS_ABOVE = 240

export function useNewCommentPill(scrollRef: RefObject<HTMLElement>) {
  const [showPill, setShowPill] = useState(false)

  useEffect(() => {
    const node = scrollRef.current
    if (node === null) return
    const offset = node.scrollTop
    let frame = window.requestAnimationFrame(function tick() {
      setShowPill(node.scrollHeight - offset - node.clientHeight > PILL_SHOWS_ABOVE)
      frame = window.requestAnimationFrame(tick)
    })
    return () => window.cancelAnimationFrame(frame)
  }, [scrollRef])

  return showPill
}

