import { useRef, useState } from 'react'

import { saveNote } from './api'
import type { DisruptedFlight } from './types'

interface RebookingNoteDockProps {
  flight: DisruptedFlight
  onPosted: (body: string) => void
}

export function RebookingNoteDock({ flight, onPosted }: RebookingNoteDockProps) {
  const [draft, setDraft] = useState('')
  const [posting, setPosting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const autosaveTimer = useRef<number | null>(null)
  const flightKey = `${flight.number}-${flight.serviceDate}`

  function scheduleAutosave(next: string) {
    if (autosaveTimer.current !== null) window.clearTimeout(autosaveTimer.current)
    autosaveTimer.current = window.setTimeout(() => {
      void saveNote({ flightKey, body: next, status: 'draft' })
    }, 600)
  }

  async function handlePost() {
    if (draft.trim() === '') return
    setPosting(true)
    setError(null)
    try {
      await saveNote({ flightKey, body: draft, status: 'posted' })
      onPosted(draft)
      setDraft('')
    } catch {
      setError('The note did not reach the desk. Check the connection and post it again.')
    } finally {
      setPosting(false)
    }
  }

  return (
    <section className="flex flex-col gap-4">
      <label htmlFor="rebooking-note" className="text-sm font-medium text-gray-700 dark:text-gray-300">
        Note for {flight.number}
      </label>
      <textarea
        id="rebooking-note"
        value={draft}
        onChange={(event) => {
          setDraft(event.target.value)
          scheduleAutosave(event.target.value)
        }}
        rows={4}
        className="rounded-md border border-gray-300 px-4 py-2 text-base leading-relaxed text-gray-900 focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 dark:border-gray-700 dark:bg-gray-950 dark:text-gray-100"
      />
      {error === null ? null : (
        <p role="alert" className="text-sm text-red-700 dark:text-red-400">
          {error}
        </p>
      )}
      <button
        type="button"
        onClick={handlePost}
        disabled={posting || draft.trim() === ''}
        className="self-start rounded-md bg-violet-700 px-4 py-2 text-base font-medium text-gray-50 hover:bg-violet-800 focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:bg-violet-600 dark:hover:bg-violet-500"
      >
        {posting ? 'Posting...' : 'Post note'}
      </button>
    </section>
  )
}

