import { act, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { saveNote } from './api'
import { RebookingNoteDock } from './RebookingNoteDock'

vi.mock('./api', () => ({ saveNote: vi.fn(() => Promise.resolve()) }))

const saveNoteMock = vi.mocked(saveNote)
const flight = { number: 'LX318', serviceDate: '2026-03-14' }
const note = 'Reaccom 14 pax on to LX318, seat block held under PNR 4KQ7XR'

beforeEach(() => {
  vi.useFakeTimers()
  saveNoteMock.mockClear()
})

afterEach(() => {
  vi.useRealTimers()
})

describe('RebookingNoteDock', () => {
  it('does not let a queued autosave land on top of the posted note', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime })
    render(<RebookingNoteDock flight={flight} onPosted={vi.fn()} />)

    await user.type(screen.getByLabelText('Note for LX318'), note)
    await user.click(screen.getByRole('button', { name: 'Post note' }))
    await act(async () => {
      vi.advanceTimersByTime(2000)
    })

    expect(saveNoteMock).toHaveBeenCalledTimes(1)
    expect(saveNoteMock).toHaveBeenCalledWith({
      flightKey: 'LX318-2026-03-14',
      body: note,
      status: 'posted',
    })
  })

  it('still autosaves a draft when the note has not been posted', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime })
    render(<RebookingNoteDock flight={flight} onPosted={vi.fn()} />)

    await user.type(screen.getByLabelText('Note for LX318'), 'Hotac list for the 0620 wave')
    await act(async () => {
      vi.advanceTimersByTime(600)
    })

    expect(saveNoteMock).toHaveBeenCalledTimes(1)
    expect(saveNoteMock).toHaveBeenCalledWith({
      flightKey: 'LX318-2026-03-14',
      body: 'Hotac list for the 0620 wave',
      status: 'draft',
    })
  })

  it('hands the posted note up and empties the box', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime })
    const onPosted = vi.fn()
    render(<RebookingNoteDock flight={flight} onPosted={onPosted} />)

    await user.type(screen.getByLabelText('Note for LX318'), note)
    await user.click(screen.getByRole('button', { name: 'Post note' }))

    expect(onPosted).toHaveBeenCalledWith(note)
    expect(screen.getByLabelText('Note for LX318')).toHaveValue('')
  })
})

