}

import type { BerthOccupancy } from './types'

const BASE = '/api/berths'

export async function assignCallsToBerth(berthId: string, callIds: string[]): Promise<void> {
  const response = await fetch(BASE + '/' + berthId + '/calls', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ callIds }),
  })
  if (!response.ok) {
    throw new Error('Berth assignment rejected with ' + response.status)
  }
}

export async function fetchOccupancy(berthId: string): Promise<BerthOccupancy> {
  const response = await fetch(BASE + '/' + berthId + '/occupancy')
  if (!response.ok) {
    throw new Error('Occupancy read rejected with ' + response.status)
  }
  return (await response.json()) as BerthOccupancy
}

