import { useState } from 'react'

import { fetchMatchingCallIds } from './dispatchApi'

interface MatchingSelectionBarProps {
  selectedCount: number
  onSelectAllMatching: (callIds: string[]) => void
}

export function MatchingSelectionBar({ selectedCount, onSelectAllMatching }: MatchingSelectionBarProps) {
  const [query, setQuery] = useState('')
  const [matchingIds, setMatchingIds] = useState<string[]>([])
  const [failed, setFailed] = useState(false)

  async function runFilter(value: string) {
    setQuery(value)
    setFailed(false)
    try {
      setMatchingIds(await fetchMatchingCallIds(value))
    } catch {
      setMatchingIds([])
      setFailed(true)
    }
  }

  return (
    <div
      role="toolbar"
      aria-label="Bulk pilot assignment"
      className="flex flex-wrap items-end gap-6 rounded-md border border-slate-200 p-4 dark:border-slate-800"
    >
      <div className="flex flex-col gap-2">
        <label htmlFor="call-filter" className="text-sm font-medium text-slate-700 dark:text-slate-300">
          Filter calls by vessel
        </label>
        <input
          id="call-filter"
          type="search"
          value={query}
