import { useState } from 'react'

export interface BulkActionState {
  pending: boolean
  error: string | null
}

export function useBulkAction<TPayload = any>(endpoint: string) {
  const [state, setState] = useState<BulkActionState>({ pending: false, error: null })

  async function run(payload: TPayload) {
    setState({ pending: true, error: null })
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (!response.ok) {
        throw new Error('Bulk action rejected with ' + response.status)
      }
      setState({ pending: false, error: null })
    } catch {
      setState({ pending: false, error: 'That bulk action did not complete. Nothing was changed.' })
    }
  }

  return { ...state, run }
}

