import { useEffect, useState } from 'react'

import { isPastLaytime } from './calc/laytime'
import { fetchExposure } from './exposureApi'
import type { ExposureTotals, Fixture } from './types'

interface BulkExposureBarProps {
  selectedFixtures: Fixture[]
  onRecalculate: () => void
}

export function BulkExposureBar({ selectedFixtures, onRecalculate }: BulkExposureBarProps) {
  const [totals, setTotals] = useState<ExposureTotals | null>(null)
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    let cancelled = false
    setFailed(false)
    fetchExposure(selectedFixtures.map((fixture) => fixture.id))
      .then((next) => {
        if (!cancelled) setTotals(next)
      })
      .catch(() => {
        if (!cancelled) setFailed(true)
      })
    return () => {
      cancelled = true
    }
  }, [selectedFixtures])

  const pastCount = selectedFixtures.filter(isPastLaytime).length

  return (
    <div
      role="toolbar"
      aria-label="Bulk fixture actions"
      className="flex flex-wrap items-center gap-6 rounded-md border border-slate-200 p-4 dark:border-slate-800"
    >
      <p className="text-base tabular-nums text-slate-700 dark:text-slate-300">
        {selectedFixtures.length} fixtures ticked
      </p>
      <p className="text-base tabular-nums text-slate-700 dark:text-slate-300">
        {pastCount} of {selectedFixtures.length} past laytime
      </p>
      {failed ? (
        <p role="alert" className="text-base text-rose-700 dark:text-rose-400">
          The exposure figures did not load. Recalculate to try again.
        </p>
      ) : totals === null ? (
        <span aria-hidden="true" className="inline-block h-6 w-32 animate-pulse rounded-md bg-slate-200 motion-reduce:animate-none dark:bg-slate-800" />
      ) : (
        <p aria-live="polite" className="text-base font-medium tabular-nums text-slate-900 dark:text-slate-100">
          {totals.currency} {totals.demurrageDue.toLocaleString('en-GB')} demurrage
        </p>
      )}
      <button
        type="button"
        onClick={onRecalculate}
        className="rounded-md bg-cyan-800 px-4 py-2 text-base font-medium text-white transition-colors hover:bg-cyan-900 focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:bg-cyan-700 dark:hover:bg-cyan-600"
      >
        Recalculate
      </button>
    </div>
  )
}

