import { ROW_HEIGHT, visibleWindow } from './windowRows'

const VIEWPORT_HEIGHT = 448

describe('visibleWindow', () => {
  it('reaches the oldest entry once the drawer is scrolled all the way down', () => {
    const total = 46
    const maxScrollTop = total * ROW_HEIGHT - VIEWPORT_HEIGHT

    expect(visibleWindow(total, maxScrollTop, VIEWPORT_HEIGHT, ROW_HEIGHT)).toEqual({
      startIndex: 38,
      endIndex: 46,
    })
  })

  it('covers the part row hanging over the bottom edge mid scroll', () => {
    expect(visibleWindow(46, 100, VIEWPORT_HEIGHT, ROW_HEIGHT)).toEqual({
      startIndex: 1,
      endIndex: 10,
    })
  })

  it('does not run past the end of a list shorter than the viewport', () => {
    expect(visibleWindow(3, 0, VIEWPORT_HEIGHT, ROW_HEIGHT)).toEqual({
      startIndex: 0,
      endIndex: 3,
    })
  })
})

