import type { KilnLogEntry } from '../types'

export interface HistoryPreferences {
  confirmBeforeRevert: boolean
  groupByShift: boolean
  hideKilnStops: boolean
  keepRevertedEntries: boolean
}

export const HISTORY_PREFERENCE_DEFAULTS: HistoryPreferences = {
  confirmBeforeRevert: true,
  groupByShift: true,
  hideKilnStops: false,
  keepRevertedEntries: false,
}

export const HISTORY_PREFERENCE_LABELS: Record<keyof HistoryPreferences, string> = {
  confirmBeforeRevert: 'Ask before reverting a log entry',
  groupByShift: 'Group entries by shift',
  hideKilnStops: 'Hide kiln stop entries',
  keepRevertedEntries: 'Keep reverted entries in the list',
}

export function withStoredPreferences(stored: Partial<HistoryPreferences>): HistoryPreferences {
  const merged: Partial<HistoryPreferences> = { ...stored }
  merged.confirmBeforeRevert ??= HISTORY_PREFERENCE_DEFAULTS.confirmBeforeRevert
  merged.groupByShift ??= HISTORY_PREFERENCE_DEFAULTS.groupByShift
  merged.hideKilnStops ??= HISTORY_PREFERENCE_DEFAULTS.hideKilnStops
  merged.keepRevertedEntries ??= HISTORY_PREFERENCE_DEFAULTS.keepRevertedEntries
  return merged as HistoryPreferences
}

export function panelEntries(entries: KilnLogEntry[], preferences: HistoryPreferences): KilnLogEntry[] {
  const kept = preferences.hideKilnStops
    ? entries.filter((entry) => entry.kind !== 'kiln-stop')
    : entries
  return preferences.keepRevertedEntries ? kept : kept.filter((entry) => entry.revertedAt === null)
}

import { describe, expect, it } from 'vitest'

import { panelEntries, withStoredPreferences } from './historyPreferences'
import type { KilnLogEntry } from '../types'

const entries: KilnLogEntry[] = [
  {
    id: 'kl-7741',
    kind: 'setpoint',
    note: 'Kiln feed 214 t/h',
    loggedBy: 'Yasmin Haddad',
    loggedAt: '2026-04-09T05:12:00Z',
    revertedAt: null,
  },
  {
    id: 'kl-7739',
    kind: 'kiln-stop',
    note: 'Stopped for brick inspection, zone 4',
    loggedBy: 'Yasmin Haddad',
    loggedAt: '2026-04-09T03:40:00Z',
    revertedAt: null,
  },
  {
    id: 'kl-7736',
    kind: 'setpoint',
    note: 'Kiln feed 208 t/h',
    loggedBy: 'Tomasz Wozniak',
    loggedAt: '2026-04-08T21:05:00Z',
    revertedAt: '2026-04-08T21:20:00Z',
  },
]

describe('withStoredPreferences', () => {
  it('keeps a switch the operator deliberately turned off', () => {
    expect(withStoredPreferences({ confirmBeforeRevert: false }).confirmBeforeRevert).toBe(false)
  })

  it('fills in a switch the operator has never touched', () => {
    expect(withStoredPreferences({}).confirmBeforeRevert).toBe(true)
  })

  it('starts the new switch off', () => {
    expect(withStoredPreferences({}).keepRevertedEntries).toBe(false)
  })
})

describe('panelEntries', () => {
  it('drops reverted entries while the new switch is off', () => {
    const preferences = withStoredPreferences({})

    expect(panelEntries(entries, preferences).map((entry) => entry.id)).toEqual([
      'kl-7741',
      'kl-7739',
    ])
  })

  it('keeps reverted entries once the switch is on', () => {
    const preferences = withStoredPreferences({ keepRevertedEntries: true })

    expect(panelEntries(entries, preferences).map((entry) => entry.id)).toEqual([
      'kl-7741',
      'kl-7739',
      'kl-7736',
    ])
  })
})

