import { useState } from 'react'

import { useSignOffHistory } from './useSignOffHistory'
import type { SignOff } from '../types'

interface SignOffTimelineProps {
  facilityId: string
  inspectorId: string
}

const WITHDRAW_WINDOW_MS = 24 * 60 * 60 * 1000

const SIGNED_ON = new Intl.DateTimeFormat('en-CA', {
  day: '2-digit',
  month: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'UTC',
})

export function SignOffTimeline({ facilityId, inspectorId }: SignOffTimelineProps) {
  const { signOffs, withdrawSignOff } = useSignOffHistory(facilityId)
  const [announcement, setAnnouncement] = useState('')

  function canWithdraw(signOff: SignOff) {
    if (signOff.kind !== 'monthly') return false
    if (signOff.inspectorId !== inspectorId) return false
    return Date.now() - new Date(signOff.signedAt).getTime() < WITHDRAW_WINDOW_MS
  }

  async function withdraw(signOff: SignOff) {
    setAnnouncement('Withdrawing the ' + signOff.kind + ' sign-off')
    if (!canWithdraw(signOff)) return
    await withdrawSignOff(signOff.id)
    setAnnouncement('Withdrew the ' + signOff.kind + ' sign-off')
  }

  return (
    <section className="flex flex-col gap-6">
      <h2 className="text-base font-semibold text-emerald-950 dark:text-emerald-50">Sign-off history</h2>
      <p role="status" aria-live="polite" className="text-sm text-emerald-900 dark:text-emerald-100">
        {announcement}
      </p>
      <ol className="flex flex-col gap-4">
        {signOffs.map((signOff) => (
          <li
            key={signOff.id}
            className="flex items-center justify-between gap-4 rounded-md border border-emerald-200 px-4 py-2 dark:border-emerald-900"
          >
            <div className="flex min-w-0 flex-col gap-2">
              <span className="truncate text-base text-emerald-950 dark:text-emerald-50">
                {signOff.kind} walkover, {signOff.inspectorName}
              </span>
              <span className="text-sm tabular-nums text-emerald-800 dark:text-emerald-200">
                {SIGNED_ON.format(new Date(signOff.signedAt))}
              </span>
            </div>
            <button
              type="button"
              onClick={() => withdraw(signOff)}
              disabled={signOff.withdrawnAt !== null}
              aria-label={'Withdraw the ' + signOff.kind + ' sign-off'}
              className="shrink-0 rounded-md border border-emerald-300 px-4 py-2 text-sm font-medium text-emerald-900 hover:bg-emerald-50 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:border-emerald-800 dark:text-emerald-100 dark:hover:bg-emerald-950"
            >
              Withdraw
            </button>
          </li>
        ))}
      </ol>
    </section>
  )
}

