import { SignOffTimeline } from './SignOffTimeline'

const mocks = vi.hoisted(() => ({ withdrawSignOff: vi.fn() }))

const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString()
const fortyDaysAgo = new Date(Date.now() - 40 * 24 * 60 * 60 * 1000).toISOString()

vi.mock('./useSignOffHistory', () => ({
  useSignOffHistory: () => ({
    signOffs: [
      {
        id: 'so-5518',
        kind: 'weekly',
        inspectorId: 'insp-204',
        inspectorName: 'Nomsa Khumalo',
        signedAt: twoHoursAgo,
        withdrawnAt: null,
      },
      {
        id: 'so-5402',
        kind: 'monthly',
        inspectorId: 'insp-204',
        inspectorName: 'Nomsa Khumalo',
        signedAt: fortyDaysAgo,
        withdrawnAt: null,
      },
    ],
    withdrawSignOff: mocks.withdrawSignOff,
  }),
}))

describe('SignOffTimeline', () => {
  beforeEach(() => {
    mocks.withdrawSignOff.mockReset()
    mocks.withdrawSignOff.mockResolvedValue(undefined)
  })

  it('withdraws a weekly walkover signed within the window', async () => {
    const user = userEvent.setup()
    render(<SignOffTimeline facilityId="tsf-north" inspectorId="insp-204" />)

    await user.click(screen.getByRole('button', { name: 'Withdraw the weekly sign-off' }))

    expect(mocks.withdrawSignOff).toHaveBeenCalledWith('so-5518')
    expect(await screen.findByText('Withdrew the weekly sign-off')).toBeInTheDocument()
  })

  it('does not leave the live region mid sentence when the window has closed', async () => {
    const user = userEvent.setup()
    render(<SignOffTimeline facilityId="tsf-north" inspectorId="insp-204" />)

    await user.click(screen.getByRole('button', { name: 'Withdraw the monthly sign-off' }))

    expect(mocks.withdrawSignOff).not.toHaveBeenCalled()
    expect(screen.getByRole('status')).toHaveTextContent(
      'That monthly sign-off can no longer be withdrawn',
    )
  })
})

