import { useState } from 'react'

import { useAnnotationHistory } from './useAnnotationHistory'
import type { AnnotationRevision } from '../types'

interface AnnotationHistoryPanelProps {
  scanId: string
}

const REVISED_ON = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'long',
  timeZone: 'UTC',
})

const CONTROL =
  'rounded-md border border-stone-300 px-4 py-2 text-sm font-medium text-stone-900 hover:bg-stone-100 focus-visible:ring-2 focus-visible:ring-amber-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none dark:border-stone-700 dark:text-stone-100 dark:hover:bg-stone-900'

export function AnnotationHistoryPanel({ scanId }: AnnotationHistoryPanelProps) {
  const { revisions, undo, redo } = useAnnotationHistory(scanId)
  const [comparing, setComparing] = useState<AnnotationRevision | null>(null)

  function openCompare(revision: AnnotationRevision) {
    setComparing(revision)
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        setComparing(null)
        return
      }
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'z') {
        event.preventDefault()
        undo()
      }
    })
  }

  return (
    <section className="flex flex-col gap-6">
      <div className="flex items-center justify-between gap-6">
        <h2 className="text-base font-semibold text-stone-900 dark:text-stone-100">Annotation history</h2>
        <div className="flex items-center gap-2">
          <button type="button" onClick={undo} className={CONTROL}>
            Undo
          </button>
          <button type="button" onClick={redo} className={CONTROL}>
            Redo
          </button>
        </div>
      </div>
      <ol className="flex flex-col gap-2">
        {revisions.map((revision) => (
          <li
            key={revision.id}
            className="flex items-center justify-between gap-4 rounded-md border border-stone-200 px-4 py-2 dark:border-stone-800"
          >
            <div className="flex min-w-0 flex-col gap-2">
              <span className="truncate text-base text-stone-900 dark:text-stone-100" title={revision.summary}>
                {revision.summary}
              </span>
              <span className="text-sm tabular-nums text-stone-600 dark:text-stone-400">
                {REVISED_ON.format(new Date(revision.revisedAt))}, {revision.author}
              </span>
            </div>
            <button
              type="button"
              onClick={() => openCompare(revision)}
              aria-label={'Compare with the ' + REVISED_ON.format(new Date(revision.revisedAt)) + ' revision'}
              className={CONTROL}
            >
              Compare
            </button>
          </li>
        ))}
      </ol>
      {comparing === null ? null : (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={'Comparing the ' + REVISED_ON.format(new Date(comparing.revisedAt)) + ' revision'}
          className="flex flex-col gap-4 rounded-md border border-stone-200 p-4 dark:border-stone-800"
        >
          <p className="text-base leading-relaxed text-stone-900 dark:text-stone-100">{comparing.summary}</p>
          <button type="button" onClick={() => setComparing(null)} className={CONTROL}>
            Close
          </button>
        </div>
      )}
    </section>
  )
}

