import { useCallback, useRef, useState, type PointerEvent as ReactPointerEvent } from 'react'

import { saveReagentPriority, type Reagent } from './reagentApi'

interface ReagentPriorityListProps {
  reagents: Reagent[]
  onReordered: (order: string[]) => void
}

function reorderSkus(skus: string[], sourceSku: string, targetSku: string) {
  const next = skus.filter((sku) => sku !== sourceSku)
  next.splice(next.indexOf(targetSku), 0, sourceSku)
  return next
}

export function ReagentPriorityList({ reagents, onReordered }: ReagentPriorityListProps) {
  const draggingSkuRef = useRef<string | null>(null)
  const [overSku, setOverSku] = useState<string | null>(null)

  const commitDrag = useCallback(
    async (targetSku: string | null) => {
      const sourceSku = draggingSkuRef.current
      if (!sourceSku || !targetSku || sourceSku === targetSku) {
        return
      }
      const order = reorderSkus(
        reagents.map((reagent) => reagent.sku),
        sourceSku,
        targetSku,
      )
      await saveReagentPriority(order)
      draggingSkuRef.current = null
      setOverSku(null)
      onReordered(order)
    },
    [reagents, onReordered],
  )

  function handlePointerUp(event: ReactPointerEvent<HTMLLIElement>) {
    if (event.pointerType === 'mouse') {
      return
    }
    void commitDrag(overSku)
  }

  return (
    <ul className="flex flex-col gap-2">
      {reagents.map((reagent) => (
        <li
          key={reagent.sku}
          draggable
          onDragStart={() => {
            draggingSkuRef.current = reagent.sku
          }}
          onDragOver={(event) => {
            event.preventDefault()
            setOverSku(reagent.sku)
          }}
          onDragEnd={() => void commitDrag(overSku)}
          onPointerUp={handlePointerUp}
          className="flex min-h-11 items-center justify-between gap-4 rounded-md border border-stone-200 bg-white px-4 py-3 text-base text-stone-900 dark:border-stone-800 dark:bg-stone-950 dark:text-stone-100"
        >
          <span className="min-w-0 flex-1 truncate" title={reagent.name}>
            {reagent.name}
          </span>
          <span className="text-sm tabular-nums text-stone-600 dark:text-stone-400">{reagent.onHand} on hand</span>
        </li>
      ))}
    </ul>
  )
}

