import type { ChromatogramRun, ColumnStats } from './types'

export interface ArchivePage {
  runs: ChromatogramRun[]
  stats: ColumnStats | null
  nextCursor: string | null
}

interface RunsResponse {
  runs: ChromatogramRun[]
  nextCursor: string | null
}

async function fetchRuns(cursor: string | null): Promise<RunsResponse> {
  const query = cursor ? '?after=' + encodeURIComponent(cursor) : ''
  const response = await fetch('/api/archive/runs' + query)
  if (!response.ok) {
    throw new Error('Run page request failed with status ' + response.status)
  }
  return (await response.json()) as RunsResponse
}

async function fetchColumnStats(cursor: string | null): Promise<ColumnStats> {
  const query = cursor ? '?after=' + encodeURIComponent(cursor) : ''
  const response = await fetch('/api/archive/column-stats' + query)
  if (!response.ok) {
    throw new Error('Column stats request failed with status ' + response.status)
  }
  return (await response.json()) as ColumnStats
}

export async function loadArchivePage(cursor: string | null): Promise<ArchivePage> {
  const [page, stats] = await Promise.all([fetchRuns(cursor), fetchColumnStats(cursor)])
  return { runs: page.runs, stats, nextCursor: page.nextCursor }
}

