async function fetchArchivePage(cursor: string | null): Promise<ArchivePage> {
  const [pageResult, statsResult] = await Promise.allSettled([fetchRuns(cursor), fetchColumnStats(cursor)])
  if (pageResult.status === 'rejected') {
    throw pageResult.reason
  }
  return {
    runs: pageResult.value.runs,
    stats: statsResult.status === 'fulfilled' ? statsResult.value : null,
    nextCursor: pageResult.value.nextCursor,
  }
}

const warmed = new Map<string, Promise<ArchivePage>>()

export async function loadArchivePage(cursor: string | null): Promise<ArchivePage> {
  if (cursor === null) {
    warmed.clear()
  }
  const alreadyWarm = cursor === null ? undefined : warmed.get(cursor)
  if (cursor !== null) {
    warmed.delete(cursor)
  }
  const page = await (alreadyWarm ?? fetchArchivePage(cursor))
  const next = page.nextCursor
  if (next !== null && !warmed.has(next)) {
    const ahead = fetchArchivePage(next)
    ahead.catch(() => warmed.delete(next))
    warmed.set(next, ahead)
  }
  return page
}

