export interface CaseFile {
  caseId: string
  productName: string
  reportedOn: string
  severity: 'serious' | 'non-serious'
}

interface CaseFeedProps {
  cases: CaseFile[]
  totalOpen: number
}

function groupByDay(cases: CaseFile[]) {
  const groups = new Map<string, CaseFile[]>()
  for (const caseFile of cases) {
    const bucket = groups.get(caseFile.reportedOn)
    if (bucket) {
      bucket.push(caseFile)
    } else {
      groups.set(caseFile.reportedOn, [caseFile])
    }
  }
  return [...groups]
}

export function CaseFeed({ cases, totalOpen }: CaseFeedProps) {
  const ordered = cases.reverse()

  return (
    <section className="flex flex-col gap-6">
      <header className="flex items-baseline justify-between gap-4">
        <h2 className="text-xl font-semibold leading-tight text-slate-900 dark:text-slate-100">Open case triage</h2>
        <p className="text-sm text-slate-600 dark:text-slate-400">{totalOpen} open, newest first</p>
      </header>
      <ul className="flex flex-col gap-2">
        {groupByDay(ordered).map(([day, dayCases]) => (
          <li key={day} className="flex flex-col gap-2">
            <h3 className="text-sm font-medium text-slate-600 dark:text-slate-400">{day}</h3>
            <ul className="flex flex-col gap-2">
              {dayCases.map((caseFile) => (
                <li
                  key={caseFile.caseId}
                  className="flex min-h-11 items-center justify-between gap-4 rounded-md border border-slate-200 px-4 py-3 dark:border-slate-800"
                >
                  <a
                    href={'/cases/' + caseFile.caseId}
                    className="text-base font-medium text-slate-900 underline-offset-2 hover:underline focus-visible:ring-2 focus-visible:ring-violet-700 focus-visible:ring-offset-2 dark:text-slate-100"
                  >
                    {caseFile.caseId}
                  </a>
                  <span className="min-w-0 flex-1 truncate text-sm text-slate-600 dark:text-slate-400">
                    {caseFile.productName}
                  </span>
                  <span className="text-sm text-slate-700 dark:text-slate-300">
                    {caseFile.severity === 'serious' ? 'Serious' : 'Non-serious'}
                  </span>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>
    </section>
  )
}

