import type { DeploymentShift, ShiftCell, ShiftTable } from './types'

export function shiftFor(shifts: ShiftTable, dayKey: string): DeploymentShift | undefined {
  return shifts[dayKey]
}

export function weekShiftSummary(shifts: ShiftTable, dayKeys: string[]): ShiftCell[] {
  return dayKeys.map((dayKey) => {
    const shift = shiftFor(shifts, dayKey)
    if (!shift) {
      return { dayKey, startsAt: null, crewSize: 0 }
    }
    return {
      dayKey,
      startsAt: shift.startsAt,
      crewSize: shift.crewSize,
    }
  })
}

export function totalCrewForWeek(shifts: ShiftTable, dayKeys: string[]) {
  return weekShiftSummary(shifts, dayKeys).reduce((sum, cell) => sum + cell.crewSize, 0)
}

