import { useEffect, useRef, useState } from 'react'

import { SlotButton } from './SlotButton'
import type { ContactSlot } from './types'

const SLOT_ROW_HEIGHT = 40

interface FirstContactPanelProps {
  slots: ContactSlot[]
  onSelect: (slot: ContactSlot) => void
  onRowsMeasured: (rows: number) => void
}

export function FirstContactPanel({ slots, onSelect, onRowsMeasured }: FirstContactPanelProps) {
  const panelRef = useRef<HTMLDivElement>(null)
  const [rows, setRows] = useState(1)

  useEffect(() => {
    const element = panelRef.current
    if (!element) return

    const observer = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (!entry) return
      window.requestAnimationFrame(() => {
        const next = Math.max(1, Math.floor(entry.contentRect.height / SLOT_ROW_HEIGHT))
        setRows(next)
        onRowsMeasured(next)
      })
    })

    observer.observe(element)
    return () => observer.disconnect()
  }, [onRowsMeasured])

  return (
    <div ref={panelRef} className="flex min-h-40 flex-col gap-2">
      <ul className="grid grid-cols-1 gap-2 sm:grid-cols-2">
        {slots.slice(0, rows * 2).map((slot) => (
          <li key={slot.id}>
            <SlotButton slot={slot} onSelect={onSelect} />
          </li>
        ))}
      </ul>
    </div>
  )
}

