import { afterEach, describe, expect, it, vi } from 'vitest'

import { FirstContactPanel } from './FirstContactPanel'

const slots = [
  { id: 'cs-4181', startsAt: '2026-06-02T09:00:00Z', adjusterId: 'adj-77' },
  { id: 'cs-4182', startsAt: '2026-06-02T09:30:00Z', adjusterId: 'adj-77' },
]

let emit: ((height: number) => void) | null = null

class StubResizeObserver {
  constructor(callback: ResizeObserverCallback) {
    emit = (height) => {
      callback(
        [{ contentRect: { height } } as unknown as ResizeObserverEntry],
        this as unknown as ResizeObserver,
      )
    }
  }
  observe() {}
  unobserve() {}
  disconnect() {}
}

vi.stubGlobal('ResizeObserver', StubResizeObserver)

afterEach(() => {
  vi.useRealTimers()
  emit = null
})

describe('FirstContactPanel', () => {
  it('reports the number of slot rows that fit', () => {
    vi.useFakeTimers()
    const onRowsMeasured = vi.fn()
    render(<FirstContactPanel slots={slots} onSelect={vi.fn()} onRowsMeasured={onRowsMeasured} />)
    emit?.(320)
    vi.advanceTimersByTime(20)
    expect(onRowsMeasured).toHaveBeenCalledWith(8)
  })

  it('drops a measurement queued while the panel is being closed', () => {
    vi.useFakeTimers()
    const onRowsMeasured = vi.fn()
    const view = render(
      <FirstContactPanel slots={slots} onSelect={vi.fn()} onRowsMeasured={onRowsMeasured} />,
    )
    emit?.(320)
    vi.advanceTimersByTime(20)
    emit?.(0)
    view.unmount()
    vi.advanceTimersByTime(20)
    expect(onRowsMeasured).toHaveBeenCalledTimes(1)
  })
})

