import { useEffect, useState } from 'react'

import { apiGet } from '../shared/api'
import type { DateRange, EffectiveDateOption } from './types'

type OptionsState =
  | { status: 'loading' }
  | { status: 'ready'; options: EffectiveDateOption[] }

export function useEffectiveDateOptions(range: DateRange, carrierIds: string[]) {
  const [state, setState] = useState<OptionsState>({ status: 'loading' })

  useEffect(() => {
    let active = true
    setState({ status: 'loading' })
    apiGet<EffectiveDateOption[]>(
      '/api/binders/effective-dates?from=' +
        range.from +
        '&to=' +
        range.to +
        '&carriers=' +
        carrierIds.join(','),
    ).then((options) => {
      if (active) {
        setState({ status: 'ready', options })
      }
    })
    return () => {
      active = false
    }
  }, [range, carrierIds])

  return state
}

