import { openScheduleTransaction } from './scheduleStore'
import { validateHearingWindow } from './validateHearingWindow'
import type { HearingDraft } from './types'

export async function saveHearingDraft(draft: HearingDraft) {
  const problem = validateHearingWindow(draft)
  if (problem) {
    return { ok: false, problem }
  }

  const tx = await openScheduleTransaction(draft.matterId)
  try {
    await tx.put('hearings', draft)
    await tx.commit()
    return { ok: true, problem: null }
  } catch (error) {
    await tx.abort()
    throw error
  }
}

import { beforeEach, describe, expect, it, vi } from 'vitest'

import { openScheduleTransaction } from './scheduleStore'
import { saveHearingDraft } from './saveHearingDraft'

vi.mock('./scheduleStore', () => ({ openScheduleTransaction: vi.fn() }))

function draftOn(startsAt: string) {
  return {
    matterId: 'mat-5518',
    hearingId: 'hr-204',
    startsAt,
    courtWindow: { opens: '2026-11-02', closes: '2026-11-30' },
    room: 'Court 4',
  }
}

function stubTransaction() {
  return {
    put: vi.fn().mockResolvedValue(undefined),
    commit: vi.fn().mockResolvedValue(undefined),
    abort: vi.fn().mockResolvedValue(undefined),
  }
}

describe('saveHearingDraft', () => {
  beforeEach(() => {
    vi.mocked(openScheduleTransaction).mockReset()
  })

  it('turns down a date outside the court window without opening a transaction', async () => {
    const result = await saveHearingDraft(draftOn('2026-12-04T10:00:00Z'))
    expect(result.problem).toBe('That date is outside the court window for this matter.')
    expect(vi.mocked(openScheduleTransaction)).not.toHaveBeenCalled()
  })

  it('still saves the next hearing after one was turned down', async () => {
    await saveHearingDraft(draftOn('2026-12-04T10:00:00Z'))
    const tx = stubTransaction()
    vi.mocked(openScheduleTransaction).mockResolvedValue(tx)
    const result = await saveHearingDraft(draftOn('2026-11-17T10:00:00Z'))
    expect(result.ok).toBe(true)
    expect(tx.commit).toHaveBeenCalledTimes(1)
  })

  it('closes the transaction when the write itself fails', async () => {
    const tx = stubTransaction()
    tx.put.mockRejectedValue(new Error('QuotaExceededError'))
    vi.mocked(openScheduleTransaction).mockResolvedValue(tx)
    await expect(saveHearingDraft(draftOn('2026-11-17T10:00:00Z'))).rejects.toThrow(
      'QuotaExceededError',
    )
    expect(tx.abort).toHaveBeenCalledTimes(1)
  })
})

