import { useCallback, useEffect, useRef, useState } from 'react'

import { saveRoundNote } from './roundsApi'

export type DraftStatus = 'idle' | 'saving' | 'saved'

interface UseRoundDraftOptions {
  roundId: string
  initialNote: string
  onSaveError: (message: string) => void
}

const SAVE_FAILED = 'Round note did not save. Check the depot connection.'

export function useRoundDraft({ roundId, initialNote, onSaveError }: UseRoundDraftOptions) {
  const [note, setNote] = useState(initialNote)
  const [status, setStatus] = useState<DraftStatus>('idle')
  const timerRef = useRef<number | null>(null)
  const pendingRef = useRef(initialNote)

  const flush = useCallback(async () => {
    if (pendingRef.current === initialNote) return
    setStatus('saving')
    await saveRoundNote(roundId, pendingRef.current)
    setStatus('saved')
  }, [initialNote, roundId])

  const edit = useCallback(
    (next: string) => {
      setNote(next)
      pendingRef.current = next
      if (timerRef.current !== null) window.clearTimeout(timerRef.current)
      timerRef.current = window.setTimeout(() => {
        flush().catch(() => onSaveError(SAVE_FAILED))
      }, 800)
    },
    [flush, onSaveError],
  )

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current)
    }
  }, [])

  return { note, status, edit }
}

