import { useEffect, useState } from 'react'

import { saveStopNote } from './stopsApi'

export interface UseStopAutosaveOptions {
  stopId: string
  savedNote: string
  isLocked: boolean
  queuedNote: string | null
}

const AUTOSAVE_MS = 900

export function useStopAutosave({ stopId, savedNote, isLocked, queuedNote }: UseStopAutosaveOptions) {
  const [note, setNote] = useState(savedNote)

  const isDirty = note !== savedNote
  const hasQueuedNote = queuedNote !== null
  const canAutosave = isDirty || hasQueuedNote && !isLocked

  useEffect(() => {
    if (!canAutosave) return
    const outgoing = isDirty ? note : queuedNote
    if (outgoing === null) return
    const id = window.setTimeout(() => {
      void saveStopNote(stopId, outgoing)
    }, AUTOSAVE_MS)
    return () => window.clearTimeout(id)
  }, [canAutosave, isDirty, note, queuedNote, stopId])

  return { note, setNote, isDirty, canAutosave }
}

