describe('useStopAutosave', () => {
  it('autosaves an edited note on an unlocked stop', () => {
    vi.useFakeTimers()
    saveStopNoteMock.mockResolvedValue(undefined)
    const { result } = renderHook(() =>
      useStopAutosave({
        stopId: 'STP-771',
        savedNote: 'Bins live in the service yard',
        isLocked: false,
        queuedNote: null,
      }),
    )

    act(() => {
      result.current.setNote('Bins live in the service yard, north gate code 2210')
    })
    act(() => {
      vi.advanceTimersByTime(900)
    })

    expect(saveStopNoteMock).toHaveBeenCalledWith('STP-771', 'Bins live in the service yard, north gate code 2210')
  })

  it('saves nothing on a locked stop, even after the driver types', () => {
    vi.useFakeTimers()
    saveStopNoteMock.mockResolvedValue(undefined)
    const { result } = renderHook(() =>
      useStopAutosave({
        stopId: 'STP-812',
        savedNote: 'Two 1100L bins, Tuesday only',
        isLocked: true,
        queuedNote: null,
