import { act, fireEvent, screen, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { renderWithProviders } from '../../test/renderWithProviders'
import { PermitForm } from './PermitForm'

const draft = {
  id: 'per-4471',
  unit: 'Two Notch unit 9',
  acres: 68,
  burnWindowStart: '2026-04-02',
  crewLead: 'Priya Raman',
}

function submitButton() {
  return screen.getByRole('button', { name: 'Submit burn permit' })
}

describe('PermitForm', () => {
  beforeEach(() => {
    vi.useFakeTimers({ shouldAdvanceTime: true })
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('disables submit while a field check is still running', () => {
    renderWithProviders(<PermitForm draft={draft} onSubmit={vi.fn()} />)
    fireEvent.blur(screen.getByLabelText('Acres to burn'))
    expect(submitButton()).toBeDisabled()
  })

  it('does not re-enable submit when the debounced check lands mid post', async () => {
    let finishPost = () => {}
    const onSubmit = vi.fn(
      () =>
        new Promise<void>((resolve) => {
          finishPost = () => resolve()
        }),
    )
    renderWithProviders(<PermitForm draft={draft} onSubmit={onSubmit} />)

    fireEvent.click(submitButton())
    fireEvent.blur(screen.getByLabelText('Acres to burn'))
    act(() => {
      vi.advanceTimersByTime(500)
    })

    expect(submitButton()).toBeDisabled()
    fireEvent.click(submitButton())
    expect(onSubmit).toHaveBeenCalledTimes(1)

    finishPost()
    await waitFor(() => expect(onSubmit).toHaveBeenCalledTimes(1))
  })
})

