import { forwardRef, useImperativeHandle, useRef } from 'react'

import type { ScaleTicket } from '../types'

export interface TicketListHandle {
  jumpToNextUnweighed: () => void
}

interface TicketListProps {
  tickets: ScaleTicket[]
}

export const TicketList = forwardRef<TicketListHandle, TicketListProps>(function TicketList({ tickets }, ref) {
  const listRef = useRef<HTMLUListElement>(null)

  useImperativeHandle(
    ref,
    () => ({
      jumpToNextUnweighed() {
        const next = tickets.find((ticket) => ticket.weighedAt === null)
        if (!next) {
          return
        }
        const row = listRef.current?.querySelector<HTMLLIElement>('#ticket-' + next.id)
        row?.focus()
        row?.scrollIntoView({ block: 'center' })
      },
    }),
    [],
  )

  return (
    <ul ref={listRef} className="flex flex-col gap-2">
      {tickets.map((ticket) => (
        <li
          key={ticket.id}
          id={'ticket-' + ticket.id}
          tabIndex={-1}
