import { act, render, screen } from '@testing-library/react'
import { beforeAll, describe, expect, it, vi } from 'vitest'

import { TicketList } from './TicketList'
import type { TicketListHandle } from './TicketList'

const atMount = [
  { id: 'st-9041', hauler: 'Okanagan Hauling', weighedAt: '2026-05-04T14:12:00Z', netTonnes: 31.4 },
  { id: 'st-9042', hauler: 'Raman Log Transport', weighedAt: null, netTonnes: 0 },
]

const afterRefresh = [
  { id: 'st-9041', hauler: 'Okanagan Hauling', weighedAt: '2026-05-04T14:12:00Z', netTonnes: 31.4 },
  { id: 'st-9042', hauler: 'Raman Log Transport', weighedAt: '2026-05-04T15:02:00Z', netTonnes: 28.7 },
  { id: 'st-9043', hauler: 'Nass Valley Chip', weighedAt: null, netTonnes: 0 },
]

beforeAll(() => {
  window.HTMLElement.prototype.scrollIntoView = vi.fn()
})

describe('TicketList', () => {
  it('jumps to the ticket that is unweighed now, not the one that was unweighed at mount', () => {
    const handle = createRef<TicketListHandle>()
    const { rerender } = render(<TicketList ref={handle} tickets={atMount} />)
    rerender(<TicketList ref={handle} tickets={afterRefresh} />)

