const UNITS = ['B', 'KB', 'MB', 'GB']

export function formatBytes(bytes: number): string {
  if (bytes <= 0) {
    return '0 B'
  }
  const exponent = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), UNITS.length - 1)
  const scaled = bytes / Math.pow(1024, exponent)
  return (exponent === 0 ? String(bytes) : scaled.toFixed(1)) + ' ' + UNITS[exponent]
}

import type { WardAttachment } from './types'

export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024

export function isWithinAttachmentLimit(attachment: WardAttachment): boolean {
  return attachment.sizeBytes <= MAX_ATTACHMENT_BYTES
}

export function tooLargeMessage(sizeBytes: number): string {
  const attemptedMb = (sizeBytes / 1000 / 1000).toFixed(2)
  const limitMb = (MAX_ATTACHMENT_BYTES / 1000 / 1000).toFixed(2)
  return (
    'That radiograph is ' +
    attemptedMb +
    ' MB. Attachments have to be under ' +
    limitMb +
    ' MB while the staged upload flag is on for this ward.'
  )
}

