/**
 * Week number of a staged flag ramp, 1 on the day the ramp starts. A ramp that
 * begins mid-week still spends a full seven days in week 1.
 */
export function rampWeek(startedAt: Date, now: Date): number {
  const elapsedDays = Math.floor((now.getTime() - startedAt.getTime()) / DAY_MS)
  if (elapsedDays < 0) {
    return 1
  }

  return Math.floor(elapsedDays / 7) + 1
}

