import { useCallback, useEffect, useState } from 'react'

import { fetchCohortMembers, removeCohortMember } from './cohortApi'
import type { CohortMember } from './types'

export function useCohortMembers(flagKey: string) {
  const [members, setMembers] = useState<CohortMember[]>([])
  const [error, setError] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    try {
      const next = await fetchCohortMembers(flagKey)
      setMembers(next)
      setError(null)
    } catch {
      setError('Could not load the cohort for ' + flagKey + '. Try again.')
    }
  }, [flagKey])

  useEffect(() => {
    void refresh()
  }, [refresh])

  const remove = useCallback(
    async (practiceId: string) => {
      setMembers((current) => current.filter((member) => member.practiceId !== practiceId))
      await removeCohortMember(flagKey, practiceId)
      await refresh()
    },
    [flagKey, refresh],
  )

  return { members, error, refresh, remove }
}

