import { renderHook } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { useFlagBroadcast } from './useFlagBroadcast'
import type { FlagChangeMessage } from './types'

class FakeChannel {
  static open: FakeChannel[] = []

  onmessage: ((message: MessageEvent<FlagChangeMessage>) => void) | null = null

  constructor(public name: string) {
    FakeChannel.open.push(this)
  }

  close() {
    FakeChannel.open = FakeChannel.open.filter((channel) => channel !== this)
  }
}

function broadcast(data: FlagChangeMessage) {
  for (const channel of [...FakeChannel.open]) {
    channel.onmessage?.(new MessageEvent('message', { data }))
  }
}

vi.stubGlobal('BroadcastChannel', FakeChannel)

afterEach(() => {
  FakeChannel.open = []
})

describe('useFlagBroadcast', () => {
  it('leaves one open channel behind after switching flags', () => {
    const onRemoteChange = vi.fn()
    const { rerender } = renderHook(({ flagKey }) => useFlagBroadcast(flagKey, onRemoteChange), {
      initialProps: { flagKey: 'biosecurity-audit-v4' },
    })

    rerender({ flagKey: 'visit-notes-v2' })
    rerender({ flagKey: 'biosecurity-audit-v4' })
    rerender({ flagKey: 'visit-notes-v2' })

    expect(FakeChannel.open).toHaveLength(1)
  })

  it('announces a remote change once, not once per flag ever opened', () => {
    const onRemoteChange = vi.fn()
    const { rerender } = renderHook(({ flagKey }) => useFlagBroadcast(flagKey, onRemoteChange), {
      initialProps: { flagKey: 'biosecurity-audit-v4' },
    })

    rerender({ flagKey: 'visit-notes-v2' })
    broadcast({ flagKey: 'visit-notes-v2', enabled: true })

    expect(onRemoteChange).toHaveBeenCalledTimes(1)
    expect(onRemoteChange).toHaveBeenCalledWith(true)
  })

  it('stops listening once the hook unmounts', () => {
    const onRemoteChange = vi.fn()
    const { unmount } = renderHook(() => useFlagBroadcast('visit-notes-v2', onRemoteChange))

    unmount()
    broadcast({ flagKey: 'visit-notes-v2', enabled: false })

    expect(onRemoteChange).not.toHaveBeenCalled()
  })
})

