import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import '@testing-library/jest-dom/vitest'

import { FlagKeyRow } from './FlagKeyRow'
import type { FlagKeyEntry } from './types'

const entry: FlagKeyEntry = {
  id: 'key-3312',
  value: 'vaxcard.reminder_card_v2',
}

const writeText = vi.fn()

beforeEach(() => {
  writeText.mockReset()
  Object.defineProperty(navigator, 'clipboard', {
    value: { writeText },
    configurable: true,
  })
})

afterEach(() => {
  vi.restoreAllMocks()
})

function renderRow() {
  return render(
    <ul>
      <FlagKeyRow entry={entry} />
    </ul>,
  )
}

describe('FlagKeyRow', () => {
  it('confirms a copy on the row', async () => {
    writeText.mockResolvedValue(undefined)
    renderRow()

    await userEvent.click(screen.getByRole('button', { name: 'Copy key' }))

    expect(writeText).toHaveBeenCalledWith('vaxcard.reminder_card_v2')
    expect(await screen.findByText('Copied')).toBeVisible()
  })

  it('explains a refused copy instead of staying silent', async () => {
    writeText.mockRejectedValue(new Error('Write permission denied'))
    renderRow()

    await userEvent.click(screen.getByRole('button', { name: 'Copy key' }))

    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Copy blocked, select the key and copy it by hand.',
    )
  })

  it('does not touch state when the clipboard settles after the row is gone', async () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {})
    let settle = () => {}
    writeText.mockReturnValue(
      new Promise<void>((resolve) => {
        settle = () => resolve()
      }),
    )
    const { unmount } = renderRow()

    await userEvent.click(screen.getByRole('button', { name: 'Copy key' }))
    unmount()
    settle()

    await waitFor(() => expect(writeText).toHaveBeenCalledTimes(1))
    expect(consoleError).not.toHaveBeenCalled()
  })
})

