import { useMemo, useState } from 'react'

import { ACCOUNT_DEFAULT_BAND_PREFS, formatDownlinkSummary } from './bandPrefs'
import type { BandId, BandPrefs } from './types'

interface DownlinkPrefsPanelProps {
  savedPrefs: Map<BandId, BandPrefs>
  onSave: (bandId: BandId, prefs: BandPrefs) => void
}

const BAND_TABS: { id: BandId; label: string }[] = [
  { id: 'x', label: 'X band' },
  { id: 'ku', label: 'Ku band' },
  { id: 'ka', label: 'Ka band' },
]

function resolveBandPrefs(savedPrefs: Map<BandId, BandPrefs>, bandId: BandId): BandPrefs {
  return savedPrefs.get(bandId) ?? ACCOUNT_DEFAULT_BAND_PREFS[bandId]
}

export function DownlinkPrefsPanel({ savedPrefs, onSave }: DownlinkPrefsPanelProps) {
  const [bandId, setBandId] = useState<BandId>('x')

  const prefs = resolveBandPrefs(savedPrefs, bandId)
  const summary = useMemo(() => formatDownlinkSummary(prefs), [prefs])

  return (
    <section className="mx-auto flex max-w-7xl flex-col gap-6">
      <div role="tablist" aria-label="Downlink band" className="flex gap-2">
        {BAND_TABS.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={tab.id === bandId}
            onClick={() => setBandId(tab.id)}
            className="rounded-md border border-slate-300 px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100 focus-visible:ring-2 focus-visible:ring-sky-700 focus-visible:ring-offset-2 aria-selected:border-sky-700 aria-selected:text-sky-800 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-900 dark:aria-selected:text-sky-300"
