      <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
        <div className="flex flex-col gap-2">
          <label htmlFor="symbol-rate" className="text-sm font-medium text-slate-700 dark:text-slate-300">
            Symbol rate (Mbaud)
          </label>
          <input
            id="symbol-rate"
            type="number"
            value={prefs.symbolRateMbaud}
            onChange={(event) => onSave(bandId, { ...prefs, symbolRateMbaud: Number(event.target.value) })}
