        </div>
        <div className="flex flex-col gap-2">
          <label htmlFor="polarisation" className="text-sm font-medium text-slate-700 dark:text-slate-300">
            Polarisation
          </label>
          <select
            id="polarisation"
            value={prefs.polarisation}
            onChange={(event) => onSave(bandId, { ...prefs, polarisation: event.target.value as BandPrefs['polarisation'] })}
