function separatorsFor(locale: string) {
  const parts = new Intl.NumberFormat(locale).formatToParts(12345.6)
  const group = parts.find((part) => part.type === 'group')?.value ?? ','
  const decimal = parts.find((part) => part.type === 'decimal')?.value ?? '.'
  return { group, decimal }
}

export function formatThreshold(valueC: number, locale: string) {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  }).format(valueC)
}

export function parseThreshold(raw: string, locale: string): number | null {
  const { group, decimal } = separatorsFor(locale)
  const normalised = raw.trim().split(group).join('').replace(decimal, '.')
  if (normalised === '' || !/^-?\d*\.?\d*$/.test(normalised)) return null
  const valueC = Number(normalised)
  return Number.isFinite(valueC) ? valueC : null
}

