      <label htmlFor={fieldId} className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        {label}
      </label>
      <input
        id={fieldId}
        type="text"
        inputMode="decimal"
        value={draft}
        aria-invalid={error !== null}
        aria-describedby={error === null ? undefined : fieldId + '-error'}
        onChange={(event) => setDraft(event.target.value)}
        onBlur={commit}
        className="rounded-md border border-zinc-300 px-4 py-2 text-base tabular-nums text-zinc-900 focus-visible:ring-2 focus-visible:ring-teal-700 focus-visible:ring-offset-2 disabled:opacity-50 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
      />
      {error === null ? null : (
        <p id={fieldId + '-error'} role="alert" className="text-sm text-red-700 dark:text-red-400">
          {error}
        </p>
      )}
      <p className="text-sm text-zinc-600 dark:text-zinc-400">
        Last changed {new Date(lastChangedAt).toLocaleDateString(locale)}
      </p>
    </div>
  )
}

