import { useCallback, useEffect, useMemo, useReducer } from 'react'

import type { RoutingChannel, RoutingPrefs } from './types'

interface RoutingPrefsPanelProps {
  savedPrefs: RoutingPrefs
  onPersist: (prefs: RoutingPrefs) => Promise<void>
}

type RoutingAction =
  | { type: 'set-channel'; channel: RoutingChannel }
  | { type: 'set-quiet-hours'; quietHours: boolean }
  | { type: 'commit' }

interface RoutingState {
  saved: RoutingPrefs
  draft: RoutingPrefs
}

function routingReducer(state: RoutingState, action: RoutingAction): RoutingState {
  switch (action.type) {
    case 'set-channel':
      return { ...state, draft: { ...state.draft, channel: action.channel } }
    case 'set-quiet-hours':
      return { ...state, draft: { ...state.draft, quietHours: action.quietHours } }
    case 'commit':
      return { ...state, saved: state.draft }
    default:
      return state
  }
}

const CHANNEL_LABELS: Record<RoutingChannel, string> = {
  pager: 'Duty pager',
  'shift-phone': 'Shift phone',
  'ops-room': 'Ops room screen',
}

export function RoutingPrefsPanel({ savedPrefs, onPersist }: RoutingPrefsPanelProps) {
  const [state, dispatch] = useReducer(routingReducer, { saved: savedPrefs, draft: savedPrefs })

  const isDirty = state.draft !== state.saved
  const channelNote = useMemo(
    () => CHANNEL_LABELS[state.draft.channel] + ' takes every alert for this shift.',
    [state.draft.channel],
  )

  const commitDraft = useCallback(() => {
    if (!isDirty) return
    void onPersist(state.draft)
    dispatch({ type: 'commit' })
  }, [])

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if ((event.ctrlKey || event.metaKey) && event.key === 's') {
        event.preventDefault()
        commitDraft()
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [commitDraft])

  return (
    <section className="flex flex-col gap-6">
      <div className="flex flex-col gap-2">
        <label htmlFor="alert-channel" className="text-sm font-medium text-stone-700 dark:text-stone-300">
