        >
          {Object.entries(CHANNEL_LABELS).map(([value, label]) => (
            <option key={value} value={value}>
              {label}
            </option>
          ))}
        </select>
        <p className="text-sm text-stone-600 dark:text-stone-400">{channelNote}</p>
      </div>

      <button
        type="button"
        disabled={!isDirty}
        onClick={() => {
          void onPersist(state.draft)
          dispatch({ type: 'commit' })
        }}
        className="self-start rounded-md bg-indigo-700 px-4 py-2 text-base font-medium text-white hover:bg-indigo-800 focus-visible:ring-2 focus-visible:ring-indigo-700 focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 dark:bg-indigo-600 dark:hover:bg-indigo-500"
      >
        Save routing
      </button>
    </section>
  )
}

