import type { MutedStation } from './types'

export interface MutedStationPages {
  byPage: Map<number, MutedStation[]>
  lastPage: number
}

export const emptyPageState: MutedStationPages = { byPage: new Map(), lastPage: 0 }

export function withPage(state: MutedStationPages, page: number, rows: MutedStation[]): MutedStationPages {
  const byPage = new Map(state.byPage)
  byPage.set(page, rows)
  return { byPage, lastPage: Math.max(state.lastPage, page) }
}

export function flattenPages(state: MutedStationPages): MutedStation[] {
  return [...state.byPage.keys()]
    .sort((left, right) => left - right)
    .flatMap((page) => state.byPage.get(page) ?? [])
}

import { useCallback, useEffect, useRef, useState } from 'react'

import { emptyPageState, flattenPages, withPage } from './mutedStationPages'
import { fetchMutedStationPage } from './mutedStationsApi'

export function useMutedStationPages(query: string) {
  const [pageState, setPageState] = useState(emptyPageState)
  const [hasMore, setHasMore] = useState(true)
  const [status, setStatus] = useState<'idle' | 'loading' | 'error'>('idle')
  const inFlight = useRef(false)

  const loadPage = useCallback(
    async (page: number) => {
      if (inFlight.current) return
      inFlight.current = true
      setStatus('loading')
      try {
        const result = await fetchMutedStationPage({ page, query })
        setPageState((current) => withPage(current, page, result.rows))
        setHasMore(result.hasMore)
        setStatus('idle')
      } catch {
        setStatus('error')
      } finally {
        inFlight.current = false
      }
    },
    [query],
  )

  useEffect(() => {
    setPageState(emptyPageState)
    void loadPage(1)
  }, [loadPage])

  const loadMore = useCallback(() => {
    void loadPage(pageState.lastPage + 1)
  }, [loadPage, pageState.lastPage])

  return { rows: flattenPages(pageState), status, hasMore, loadMore }
}

