function station(stationId: string, name: string) {
  return { stationId, name, mutedUntil: '2026-08-04T00:00:00Z' }
}

describe('mutedStationPages', () => {
  it('keeps pages in page order however they land', () => {
    const late = withPage(emptyPageState, 3, [station('gs-31', 'Svalbard 3')])
    const both = withPage(late, 2, [station('gs-22', 'Punta Arenas 2')])

    expect(flattenPages(both).map((row) => row.stationId)).toEqual(['gs-22', 'gs-31'])
  })

  it('replaces a page instead of holding it twice', () => {
    const once = withPage(emptyPageState, 2, [station('gs-22', 'Punta Arenas 2')])
    const twice = withPage(once, 2, [station('gs-22', 'Punta Arenas 2')])

    expect(flattenPages(twice)).toHaveLength(1)
  })
})

describe('useMutedStationPages', () => {
  it('asks for each page once when load more is pressed twice in a row', async () => {
    fetchPage.mockResolvedValue({ rows: [station('gs-11', 'Kiruna 1')], hasMore: true })
    const { result } = renderHook(() => useMutedStationPages(''))

    await waitFor(() => expect(result.current.rows).toHaveLength(1))

    act(() => {
      result.current.loadMore()
      result.current.loadMore()
    })
    await waitFor(() => expect(result.current.rows).toHaveLength(2))

