const ELLIPSIS = '...'

export const TAB_LABEL_MAX = 32
export const MENU_LABEL_MAX = 48

export function fitLabel(name: string, maxChars: number) {
  const trimmed = name.trim()
  if (trimmed.length <= maxChars) return trimmed
  return trimmed.slice(0, maxChars - ELLIPSIS.length) + ELLIPSIS
}

export function savedViewLabel(name: string) {
  return fitLabel(name, TAB_LABEL_MAX)
}

export function savedViewMenuLabel(name: string) {
  return fitLabel(name, MENU_LABEL_MAX)
}

