import { useEffect, useState } from 'react'

import type { PreferenceKey, PreferenceValues } from './types'

const values: PreferenceValues = {
  units: 'metric',
  timeFormat: 'utc',
  decomProfile: 'ccsds-b',
}

const listeners = new Map<PreferenceKey, Set<() => void>>()

export function getPreference<K extends PreferenceKey>(key: K): PreferenceValues[K] {
  return values[key]
}

export function setPreference<K extends PreferenceKey>(key: K, value: PreferenceValues[K]) {
  values[key] = value
  listeners.get(key)?.forEach((listener) => listener())
}

export function subscribe(key: PreferenceKey, listener: () => void) {
  const forKey = listeners.get(key) ?? new Set<() => void>()
  forKey.add(listener)
  listeners.set(key, forKey)

  return () => {
    forKey.delete(listener)
    if (forKey.size === 0) listeners.delete(key)
  }
}

export function usePreference<K extends PreferenceKey>(key: K) {
  const [value, setValue] = useState(() => getPreference(key))

  useEffect(() => {
    setValue(getPreference(key))
    return subscribe(key, () => setValue(getPreference(key)))
  }, [key])

  return value
}

import { act, render, screen } from '@testing-library/react'
import { beforeEach, describe, expect, it } from 'vitest'

import { setPreference, usePreference } from './preferencesStore'

interface ReadoutProps {
  label: string
}

function UnitsReadout({ label }: ReadoutProps) {
  const units = usePreference('units')

  return (
    <p>
      {label}: {units}
    </p>
  )
}

describe('usePreference', () => {
  beforeEach(() => {
    setPreference('units', 'metric')
  })

  it('keeps feeding the panels still on screen after another one unmounts', () => {
    const { rerender } = render(
      <>
        <UnitsReadout label="Header" />
        <UnitsReadout label="Inspector" />
      </>,
    )
    expect(screen.getByText('Header: metric')).toBeInTheDocument()

    rerender(
      <>
        <UnitsReadout label="Header" />
      </>,
    )
    act(() => {
      setPreference('units', 'imperial')
    })

    expect(screen.getByText('Header: imperial')).toBeInTheDocument()
  })

  it('shows the value already in the store when a panel mounts', () => {
    setPreference('units', 'imperial')
    render(<UnitsReadout label="Header" />)

    expect(screen.getByText('Header: imperial')).toBeInTheDocument()
  })
})

import { useCallback, useRef, useState } from 'react'

import type { ChecklistPrefs } from './types'

export function useRetrySave(save: (prefs: ChecklistPrefs) => Promise<void>) {
  const [status, setStatus] = useState<'idle' | 'saving' | 'failed'>('idle')
  const inFlight = useRef(false)

  const retry = useCallback(
    async (prefs: ChecklistPrefs) => {
      if (inFlight.current) return
      inFlight.current = true
      setStatus('saving')
      try {
        await save(prefs)
        setStatus('idle')
      } catch {
        setStatus('failed')
      } finally {
        inFlight.current = false
      }
    },
    [save],
  )

  return { status, retry }
}

