import { useMemo, useState } from 'react'

import { CrewPrefRow } from './CrewPrefRow'
import type { CrewMember, NotificationChannel, RowDensity } from './types'

interface CrewNotificationsPanelProps {
  crew: CrewMember[]
  density: RowDensity
  timeZone: string
  onToggle: (crewId: string, channel: NotificationChannel) => void
  onQuietHoursChange: (startHour: number) => void
}

export function useCrewRowConfig(density: RowDensity, timeZone: string) {
  return useMemo(() => ({ density, timeZone, unitLabel: 'passes / week' }), [density, timeZone])
}

export function CrewNotificationsPanel({
  crew,
  density,
  timeZone,
  onToggle,
  onQuietHoursChange,
}: CrewNotificationsPanelProps) {
  const [quietHoursStart, setQuietHoursStart] = useState(22)
  const rowConfig = useCrewRowConfig(density, timeZone)

  return (
    <section className="flex flex-col gap-6">
      <div className="flex flex-col gap-2">
        <label htmlFor="quiet-hours-start" className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
          Quiet hours start
        </label>
        <input
          id="quiet-hours-start"
          type="range"
          min={18}
          max={23}
          value={quietHoursStart}
          onChange={(event) => {
            const hour = Number(event.target.value)
            setQuietHoursStart(hour)
            onQuietHoursChange(hour)
          }}
          className="w-full focus-visible:ring-2 focus-visible:ring-cyan-700 focus-visible:ring-offset-2"
        />
        <p className="text-sm tabular-nums text-neutral-600 dark:text-neutral-400">
          Pass reminders pause from {quietHoursStart}:00 until 06:00.
        </p>
      </div>

      <ul className="flex flex-col gap-2">
        {crew.map((member) => (
          <CrewPrefRow key={member.crewId} member={member} config={rowConfig} onToggle={onToggle} />
        ))}
      </ul>
    </section>
  )
}

import { fireEvent, render, renderHook, screen } from '@testing-library/react'
import { memo, useState } from 'react'
import { describe, expect, it, vi } from 'vitest'

import { useCrewRowConfig } from './CrewNotificationsPanel'

const rowRenders = vi.fn()

interface ProbeRowProps {
  config: ReturnType<typeof useCrewRowConfig>
}

const ProbeRow = memo(function ProbeRow({ config }: ProbeRowProps) {
  rowRenders()

  return <span>{config.unitLabel}</span>
})

interface HarnessProps {
  timeZone: string
}

function Harness({ timeZone }: HarnessProps) {
  const [quietHours, setQuietHours] = useState(false)
  const config = useCrewRowConfig('comfortable', timeZone)

  return (
    <div>
      <button type="button" onClick={() => setQuietHours((on) => !on)}>
        Quiet hours {quietHours ? 'on' : 'off'}
      </button>
      <ProbeRow config={config} />
    </div>
  )
}

describe('useCrewRowConfig', () => {
  it('hands back the same object when nothing a row cares about changed', () => {
    const { result, rerender } = renderHook(({ density }) => useCrewRowConfig(density, 'Europe/Madrid'), {
      initialProps: { density: 'comfortable' as const },
    })
    const first = result.current

    rerender({ density: 'comfortable' as const })

    expect(result.current).toBe(first)
  })

  it('hands back a new object when the density preference changes', () => {
    const { result, rerender } = renderHook(({ density }) => useCrewRowConfig(density, 'Europe/Madrid'), {
      initialProps: { density: 'comfortable' as const },
    })
    const first = result.current

    rerender({ density: 'compact' as const })

    expect(result.current).not.toBe(first)
    expect(result.current.density).toBe('compact')
  })

  it('leaves a memoized row alone while an unrelated control in the panel moves', () => {
    render(<Harness timeZone="Europe/Madrid" />)
    expect(rowRenders).toHaveBeenCalledTimes(1)

    fireEvent.click(screen.getByRole('button', { name: 'Quiet hours off' }))

    expect(screen.getByRole('button', { name: 'Quiet hours on' })).toBeInTheDocument()
    expect(rowRenders).toHaveBeenCalledTimes(1)
  })
})
